async function novaSecretsRequest(request){const user=(request.headers.get('Cf-Access-Authenticated-User-Email')||'').trim().toLowerCase();if(user!=='elsousypharmacy@gmail.com')return new Response(JSON.stringify({ok:false,error:'Unauthorized'}),{status:403,headers:{'content-type':'application/json','cache-control':'no-store'}});const h={'content-type':'application/json','cache-control':'no-store'};if(request.method==='GET'&&new URL(request.url).searchParams.get('action')==='whatsapp-test')return novaWhatsAppConnectionTest();if(request.method==='GET'){if(!request.headers.get('accept')?.includes('application/json'))return new Response(NOVA_SECRETS_ADMIN_HTML,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store'}});const keys=['WA_TOKEN','WA_PHONE_ID','NOVA_WA_BRIDGE_TOKEN','WA_BACKEND_URL','PHARMAOVERSEAS_API_KEY'];const saved=[];for(const k of keys){if(await NOVA_SECRETS_KV.get('secret:'+k))saved.push(k)}return new Response(JSON.stringify({ok:true,saved}),{headers:h})}if(request.method!=='PUT')return new Response(JSON.stringify({error:'Method not allowed'}),{status:405,headers:h});const body=await request.json().catch(()=>null);const allowed=['WA_TOKEN','WA_PHONE_ID','NOVA_WA_BRIDGE_TOKEN','WA_BACKEND_URL','PHARMAOVERSEAS_API_KEY'];if(!body||!allowed.includes(body.key)||typeof body.value!=='string'||!body.value.trim()||body.value.length>12000)return new Response(JSON.stringify({ok:false,error:'Invalid input'}),{status:400,headers:h});const raw=NOVA_SECRET_ENCRYPTION_KEY;if(!raw||!NOVA_SECRETS_KV)return new Response(JSON.stringify({ok:false,error:'Storage not configured'}),{status:503,headers:h});const key=await crypto.subtle.importKey('raw',new Uint8Array(raw.match(/.{2}/g).map(x=>parseInt(x,16))),{name:'AES-GCM'},false,['encrypt']);const iv=crypto.getRandomValues(new Uint8Array(12));const encrypted=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(body.value)));const record={v:1,iv:Array.from(iv),data:Array.from(encrypted)};await NOVA_SECRETS_KV.put('secret:'+body.key,JSON.stringify(record));return new Response(JSON.stringify({ok:true}),{headers:h})}
