/* NOVA_STATIC_ASSETS_BEGIN */
const NOVA_STATIC_ASSETS={"/nova-icons.js":{"body":"/* UX40: one inline SVG sprite (stroke 1.75, currentColor, 16px default, 20px in headings).\n   Replaces emoji/text glyphs in buttons and headings (static and dynamic) with <svg><use>. */\n(function () {\n  if (window.NovaIcons) return;\n  var P = {\n    x: '<path d=\"M6 6l12 12M18 6L6 18\"/>',\n    check: '<path d=\"M5 12.5l4.5 4.5L19 7.5\"/>',\n    sparkle: '<path d=\"M12 3l1.9 5.6L19.5 10.5l-5.6 1.9L12 18l-1.9-5.6L4.5 10.5l5.6-1.9z\"/><path d=\"M19 3v4M17 5h4\"/>',\n    lock: '<rect x=\"5\" y=\"11\" width=\"14\" height=\"9\" rx=\"2\"/><path d=\"M8 11V8a4 4 0 0 1 8 0v3\"/>',\n    gear: '<circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M12 3v2.5M12 18.5V21M3 12h2.5M18.5 12H21M5.6 5.6l1.8 1.8M16.6 16.6l1.8 1.8M18.4 5.6l-1.8 1.8M7.4 16.6l-1.8 1.8\"/>',\n    printer: '<path d=\"M7 9V4h10v5\"/><rect x=\"4\" y=\"9\" width=\"16\" height=\"8\" rx=\"2\"/><path d=\"M7 14h10v6H7z\"/>',\n    eye: '<path d=\"M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/>',\n    refresh: '<path d=\"M20 11a8 8 0 1 0-2.3 5.7\"/><path d=\"M20 4v7h-7\"/>',\n    warn: '<path d=\"M12 4l9 16H3z\"/><path d=\"M12 10v4M12 17.2v.1\"/>'\n  };\n  var MAP = { '✦': 'sparkle', '✕': 'x', '✓': 'check', '🔐': 'lock', '⚙️': 'gear', '⚙': 'gear', '🖨️': 'printer', '🖨': 'printer', '👁️': 'eye', '👁': 'eye', '↻': 'refresh', '⚠️': 'warn', '⚠': 'warn' };\n  var RE = /(⚙️|🖨️|👁️|⚠️|[✦✕✓🔐⚙🖨👁↻⚠])️?/u;\n  var SEL = 'button,a.btn,summary,.btn,h1,h2,h3,h4,[role=button]';\n  function svg(name) { return '<svg class=\"nova-ico\" viewBox=\"0 0 24 24\" aria-hidden=\"true\" focusable=\"false\"><use href=\"#nico-' + name + '\"/></svg>'; }\n  function sprite() {\n    if (document.getElementById('novaIconSprite') || !document.body) return;\n    var s = '<svg id=\"novaIconSprite\" xmlns=\"http://www.w3.org/2000/svg\" width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\" focusable=\"false\">';\n    for (var k in P) s += '<symbol id=\"nico-' + k + '\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.75\" stroke-linecap=\"round\" stroke-linejoin=\"round\">' + P[k] + '</symbol>';\n    var d = document.createElement('div'); d.innerHTML = s + '</svg>'; document.body.insertBefore(d.firstChild, document.body.firstChild);\n  }\n  function fix(root) {\n    if (!root || !root.nodeType) return;\n    var host = root.nodeType === 1 ? root : root.parentElement;\n    if (!host) return;\n    var els = [];\n    if (host.matches && host.matches(SEL)) els.push(host);\n    else if (host.closest) { var c = host.closest(SEL); if (c) els.push(c); }\n    if (host.querySelectorAll) els.push.apply(els, host.querySelectorAll(SEL));\n    els.forEach(function (el) {\n      var w = document.createTreeWalker(el, NodeFilter.SHOW_TEXT), hits = [], n;\n      while ((n = w.nextNode())) { if (RE.test(n.nodeValue) && !(n.parentElement && n.parentElement.closest('script,style,svg,textarea'))) hits.push(n); }\n      hits.forEach(function (t) {\n        var parts = t.nodeValue.split(new RegExp(RE.source, 'gu')), frag = document.createDocumentFragment(), only = !t.nodeValue.replace(new RegExp(RE.source, 'gu'), '').trim();\n        for (var i = 0; i < parts.length; i++) {\n          if (i % 2) { var tmp = document.createElement('span'); tmp.innerHTML = svg(MAP[parts[i]] || 'x'); frag.appendChild(tmp.firstChild); if (only && el.getAttribute && !el.getAttribute('aria-label') && !el.getAttribute('title')) el.setAttribute('aria-label', parts[i] === '✕' ? 'إغلاق' : 'icon'); }\n          else if (parts[i]) frag.appendChild(document.createTextNode(parts[i]));\n        }\n        t.parentNode.replaceChild(frag, t);\n      });\n    });\n  }\n  function start() {\n    sprite(); fix(document.body);\n    new MutationObserver(function (ms) { ms.forEach(function (m) { if (m.type === 'characterData') fix(m.target); else m.addedNodes.forEach(function (a) { if (a.nodeType === 1 || a.nodeType === 3) fix(a); }); }); })\n      .observe(document.body, { childList: true, subtree: true, characterData: true });\n  }\n  window.NovaIcons = { fix: fix, names: Object.keys(P) };\n  if (document.body) start(); else document.addEventListener('DOMContentLoaded', start);\n})();\n","type":"application/javascript"},"/nova-icons.css":{"body":"/* UX40: unified icon set */\n.nova-ico{width:16px;height:16px;flex:none;stroke:currentColor;fill:none;stroke-width:1.75;vertical-align:middle;margin-inline-end:6px;position:relative;top:-1px}\nh1 .nova-ico,h2 .nova-ico,h3 .nova-ico,h4 .nova-ico{width:20px;height:20px}\nbutton:empty .nova-ico,button>.nova-ico:only-child{margin-inline-end:0}\n[dir=rtl] .nova-ico-dir{transform:scaleX(-1)}\nbutton svg:not(.receipt-barcode-svg),a.btn svg,summary svg,.btn svg,.nova-tab svg{width:16px;height:16px}\nh1 svg,h2 svg,h3 svg,h4 svg{width:20px;height:20px}\n/* UX420: icon sizing modifiers (opt-in, logical, follow currentColor so dark/light stay consistent) */\n.nova-ico.nova-ico-sm{width:var(--nx-icon-sm,14px);height:var(--nx-icon-sm,14px)}\n.nova-ico.nova-ico-lg{width:var(--nx-icon-lg,20px);height:var(--nx-icon-lg,20px)}\n.nova-ico.nova-ico-xl{width:var(--nx-icon-xl,24px);height:var(--nx-icon-xl,24px)}\n.nova-ico{stroke-linecap:round;stroke-linejoin:round;transition:color var(--nx-dur-fast,120ms) var(--nx-ease,ease)}\n@media (prefers-reduced-motion:reduce){.nova-ico{transition:none}}\n","type":"text/css"},"/ux-tokens.css":{"body":"/* UX45: spacing + radius scale tokens (display layer only). */\n:root{--sp-1:4px;--sp-2:8px;--sp-3:12px;--sp-4:16px;--sp-5:24px;--sp-6:32px;--r-1:6px;--r-2:10px;--r-pill:999px}\n\n/* UX420: modern design tokens (Black Edition dark default, opt-in light). Additive: only --nx-* variables and opt-in .nx-* classes,\n   no global element selectors, so existing screens are unchanged until they adopt them. Mirrors ux-tokens.js (NovaUx.apply). Logical properties only (RTL-first). */\n:root{--nx-font:Cairo,Tahoma,Arial,sans-serif;\n--nx-bg-base:#08090b;--nx-bg-panel:#111418;--nx-bg-surface:#1b2026;--nx-bg-elevated:#232a32;--nx-border-subtle:#2a313a;--nx-border-focus:#76b8d5;\n--nx-text-main:#f1f3f5;--nx-text-muted:#a4adb7;--nx-text-dim:#808b96;--nx-accent:#76b8d5;--nx-on-accent:#08090b;--nx-ok:#60b99b;--nx-danger:#ff6b6b;--nx-warn:#d9bf86;\n--nx-fs-xs:12px;--nx-fs-sm:13px;--nx-fs-md:15px;--nx-fs-lg:18px;--nx-fs-xl:22px;--nx-fs-2xl:28px;--nx-lh-tight:1.3;--nx-lh-base:1.6;--nx-fw-regular:400;--nx-fw-semibold:600;--nx-fw-bold:700;\n--nx-sp-1:4px;--nx-sp-2:8px;--nx-sp-3:12px;--nx-sp-4:16px;--nx-sp-5:24px;--nx-sp-6:32px;--nx-sp-7:48px;\n--nx-r-1:6px;--nx-r-2:10px;--nx-r-3:14px;--nx-r-pill:999px;\n--nx-icon-sm:14px;--nx-icon-md:16px;--nx-icon-lg:20px;--nx-icon-xl:24px;\n--nx-shadow-1:0 1px 2px rgba(0,0,0,.5);--nx-shadow-2:0 6px 18px rgba(0,0,0,.55);\n--nx-ease:cubic-bezier(.2,.7,.2,1);--nx-dur-fast:120ms;--nx-dur-base:180ms;--nx-dur-slow:260ms;--nx-focus-ring:2px}\n[data-theme=light]{--nx-bg-base:#f6f7f9;--nx-bg-panel:#fff;--nx-bg-surface:#eef1f4;--nx-bg-elevated:#fff;--nx-border-subtle:#d5dbe1;--nx-border-focus:#0b5f85;\n--nx-text-main:#14181d;--nx-text-muted:#4a5560;--nx-text-dim:#5b6670;--nx-accent:#0b5f85;--nx-on-accent:#fff;--nx-ok:#0d6b4d;--nx-danger:#b42318;--nx-warn:#8a5a00;\n--nx-shadow-1:0 1px 2px rgba(20,24,29,.12);--nx-shadow-2:0 6px 18px rgba(20,24,29,.16)}\n/* Opt-in components. */\n.nx-card{background:var(--nx-bg-panel);color:var(--nx-text-main);border:1px solid var(--nx-border-subtle);border-radius:var(--nx-r-3);padding:var(--nx-sp-4);box-shadow:var(--nx-shadow-1);transition:box-shadow var(--nx-dur-base) var(--nx-ease),border-color var(--nx-dur-base) var(--nx-ease)}\n.nx-card--elevated{background:var(--nx-bg-elevated);box-shadow:var(--nx-shadow-2)}\n.nx-card:hover{border-color:var(--nx-border-focus)}\n.nx-h1{font:var(--nx-fw-bold) var(--nx-fs-2xl)/var(--nx-lh-tight) var(--nx-font)}\n.nx-h2{font:var(--nx-fw-semibold) var(--nx-fs-xl)/var(--nx-lh-tight) var(--nx-font)}\n.nx-h3{font:var(--nx-fw-semibold) var(--nx-fs-lg)/var(--nx-lh-tight) var(--nx-font)}\n.nx-text{font:var(--nx-fw-regular) var(--nx-fs-md)/var(--nx-lh-base) var(--nx-font)}\n.nx-text-muted{color:var(--nx-text-muted);font-size:var(--nx-fs-sm)}\n.nx-btn{display:inline-flex;align-items:center;justify-content:center;gap:var(--nx-sp-2);min-block-size:40px;padding-block:var(--nx-sp-2);padding-inline:var(--nx-sp-4);border:1px solid var(--nx-border-subtle);border-radius:var(--nx-r-2);background:var(--nx-bg-surface);color:var(--nx-text-main);font:var(--nx-fw-semibold) var(--nx-fs-md)/1 var(--nx-font);cursor:pointer;transition:background-color var(--nx-dur-fast) var(--nx-ease),border-color var(--nx-dur-fast) var(--nx-ease),transform var(--nx-dur-fast) var(--nx-ease)}\n.nx-btn:hover{border-color:var(--nx-border-focus);background:var(--nx-bg-elevated)}\n.nx-btn:active{transform:translateY(1px)}\n.nx-btn:focus-visible,.nx-card:focus-visible{outline:var(--nx-focus-ring) solid var(--nx-border-focus);outline-offset:2px}\n.nx-btn:disabled,.nx-btn[aria-disabled=true]{opacity:.5;cursor:not-allowed;transform:none}\n.nx-btn--primary{background:var(--nx-accent);border-color:var(--nx-accent);color:var(--nx-on-accent)}\n.nx-btn--primary:hover{background:var(--nx-accent);filter:brightness(1.08)}\n.nx-btn--ghost{background:transparent;border-color:transparent}\n.nx-btn--danger{background:transparent;border-color:var(--nx-danger);color:var(--nx-danger)}\n.nx-ico{inline-size:var(--nx-icon-md);block-size:var(--nx-icon-md)}\n.nx-ico--sm{inline-size:var(--nx-icon-sm);block-size:var(--nx-icon-sm)}.nx-ico--lg{inline-size:var(--nx-icon-lg);block-size:var(--nx-icon-lg)}.nx-ico--xl{inline-size:var(--nx-icon-xl);block-size:var(--nx-icon-xl)}\n@media (prefers-reduced-motion:reduce){:root{--nx-dur-fast:0ms;--nx-dur-base:0ms;--nx-dur-slow:0ms}.nx-btn:active{transform:none}}\n\n/* UX214: reserve space on desktop so load-time text/i18n swaps do not shift layout (CLS). */\n@media (min-width:1100px) and (min-height:651px){\n  html body .invoice-footer{height:163px;min-height:163px;max-height:163px;box-sizing:border-box}\n  html body .nova-sale-number{min-width:72px;min-height:32px;box-sizing:border-box;display:inline-block;text-align:center}\n  html body .nova-sale-actions .nova-new-sale{min-width:114px;box-sizing:border-box}\n  html body .nova-sale-actions .nova-help-chip{min-width:88px;box-sizing:border-box}\n}\n","type":"text/css"},"/supplier-lookup.css":{"body":"/* Supplier lookup on the sale screen (Epic #53, task 08).\n   CSS lifted from the owner-approved designs in docs/procurement/ui-reference/.\n   Palette variables only; tablet landscape first. */\n\n/* Row unit inside a product suggestion row (row-unit.cjs) */\n.su{display:inline-flex;align-items:stretch;height:32px;margin-inline-start:auto;margin-inline-end:28px;align-self:center;\n  background:var(--bg-surface);border:1px solid var(--border-subtle);border-radius:6px;overflow:hidden;font-family:var(--font);font-size:12px;font-weight:600}\n.su-stock{display:flex;align-items:center;gap:7px;padding:0 12px;color:var(--text-main);white-space:nowrap}\n.su-dot{width:7px;height:7px;border-radius:50%}\n.su-low .su-dot{background:var(--accent-amber)} .su-ok .su-dot{background:var(--accent-green)}\n.su-low .su-stock b{color:var(--accent-amber)}\n.su-stock b{font:700 13px var(--font-mono)}\n.su-stock small{font-size:11px;font-weight:600;color:var(--text-muted)}\n.su-btn{display:flex;align-items:center;gap:6px;padding:0 12px;border:0;border-inline-start:1px solid var(--border-subtle);background:transparent;color:var(--accent-cyan-light);font:600 12px var(--font);cursor:pointer}\n.su-btn:hover{background:var(--bg-surface-hover)}\n.su-low .su-btn{background:rgba(56,126,158,.18)}\n.su-btn.icon{padding:0 11px}\n\n/* Empty-search row button */\n.su-empty{display:flex;align-items:center;justify-content:center;gap:8px;margin-top:8px}\n.su-empty .su-btn{border:1px solid var(--border-subtle);border-radius:6px;height:32px}\n\n@media (pointer: coarse){\n  .su{min-height:44px}\n  .su .su-btn{min-height:44px}\n  .su-empty .su-btn{min-height:44px}\n  .sp-qty .btn{min-width:44px;min-height:44px}\n  .sp-add .btn-primary{min-height:44px}\n  .ss-row .btn{min-height:44px}\n}\n\n/* Popup (popup.cjs) */\n.sp-card{max-width:720px;width:92%;max-height:84vh}\n.sp-body{overflow-y:auto;padding:12px 16px;display:flex;flex-direction:column;gap:8px}\n.sp-sec{font-size:11px;color:var(--text-dim);margin:6px 2px 0}\n.sp-group-head{font-size:12px;font-weight:700;color:var(--accent-cyan-light);margin:8px 2px 0}\n.sp-row{display:grid;grid-template-columns:1fr auto auto;gap:14px;align-items:center;background:var(--bg-surface);border:1px solid var(--border-subtle);border-radius:6px;padding:10px 12px}\n.sp-row.best{border-color:var(--accent-green)}\n.sp-row.off{opacity:.65}\n.sp-name{font-size:13px;font-weight:700;direction:ltr;text-align:right}\n.sp-meta{font-size:11px;color:var(--text-muted);margin-top:3px;display:flex;gap:8px;flex-wrap:wrap;align-items:center}\n.sp-tag{border-radius:999px;padding:1px 8px;font-size:10.5px;font-weight:600}\n.t-best{background:rgba(96,185,155,.15);color:var(--accent-green)}\n.t-ok{background:rgba(96,185,155,.10);color:var(--accent-green)}\n.t-off{background:var(--bg-surface-active);color:var(--text-muted)}\n.sp-price{text-align:left;min-width:110px}\n.sp-p{font:700 16px var(--font-mono);color:var(--text-main)}\n.sp-pub{font:11px var(--font-mono);color:var(--text-dim);text-decoration:line-through;margin-inline-end:6px}\n.sp-disc{font-size:11px;font-weight:700;color:var(--accent-amber)}\n.sp-qty{direction:ltr;display:flex;align-items:center;gap:6px}\n.sp-qty b{min-width:26px;text-align:center;font:700 13px var(--font-mono)}\n.sp-qty .btn{width:30px;padding:6px 0}\n.sp-add{display:flex;gap:8px;align-items:center}\n.sp-foot-note{margin-inline-end:auto;font-size:11px;color:var(--text-dim)}\n.sp-state{padding:28px 12px;text-align:center;color:var(--text-muted);font-size:13px}\n.sp-err{font-size:11.5px;color:var(--accent-amber);background:var(--accent-amber-bg);border-radius:6px;padding:8px 12px}\n.sp-link{border:0;background:transparent;color:var(--accent-cyan-light);font:600 11px var(--font);cursor:pointer;text-decoration:underline}\n.sp-scope{padding:8px 16px;display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;font:12px var(--font);color:var(--text-muted);border-bottom:1px solid var(--border-subtle)}\n.sp-scope .sp-link{min-height:44px}\n.sp-updated{font-size:11px;color:var(--text-dim)}\n\n/* Suppliers screen (suppliers-screen.cjs) */\n.ss-card{max-width:560px;width:92%}\n.ss-body{padding:14px 16px;display:flex;flex-direction:column;gap:10px;max-height:70vh;overflow:auto}\n.ss-row{display:flex;align-items:center;gap:12px;background:var(--bg-surface);border:1px solid var(--border-subtle);border-radius:6px;padding:12px}\n.ss-logo{width:36px;height:36px;border-radius:6px;background:var(--bg-surface-active);display:flex;align-items:center;justify-content:center;font:700 14px var(--font-mono);color:var(--accent-cyan-light)}\n.ss-name{font-size:13px;font-weight:700}.ss-sub{font-size:11px;color:var(--text-muted);margin-top:3px}\n.ss-grow{flex:1}\n.ss-tag{font-size:11px;font-weight:600;border-radius:999px;padding:3px 9px;display:inline-flex;gap:6px;align-items:center}\n.ss-ok{background:rgba(96,185,155,.14);color:var(--accent-green)} .ss-off{background:var(--bg-surface-active);color:var(--text-muted)}\n.ss-err{background:rgba(187,164,119,.16);color:var(--accent-amber)}\n.ss-dot{width:6px;height:6px;border-radius:50%;background:currentColor}\n.ss-lbl{font-size:11.5px;color:var(--text-muted);margin-bottom:5px;display:block}\n.ss-in{width:100%;height:38px;background:var(--bg-base);border:1px solid var(--border-subtle);border-radius:6px;color:var(--text-main);padding:0 12px;font:13px var(--font);box-sizing:border-box}\n.ss-note{font-size:11.5px;color:var(--text-muted);background:var(--bg-surface);border:1px solid var(--border-subtle);border-radius:6px;padding:10px 12px;line-height:1.7}\n.ss-sel{display:flex;gap:8px}.ss-opt{flex:1;border:1px solid var(--border-subtle);border-radius:6px;padding:10px;background:var(--bg-surface);font-size:12.5px;font-weight:600;text-align:center;cursor:pointer;color:var(--text-main)}\n.ss-opt.on{border-color:var(--accent-cyan-light);background:rgba(56,126,158,.18)} .ss-opt.dis{opacity:.5;cursor:default}\n.ss-opt small{display:block;font-weight:500;color:var(--text-dim);margin-top:3px;font-size:10.5px}\n.ss-msg{font-size:12px;color:var(--text-muted);min-height:16px}\n\n","type":"text/css"},"/supplier-lookup.js":{"body":"/* Supplier lookup on the sale screen (Epic #53, task 08).\n   DOM layer only: all data comes from window.NOVA_SUPPLIER_PROVIDER,\n   which the network provider (built separately) will supply. When the\n   provider is missing, buttons report that suppliers are not linked yet\n   and nothing breaks. Passwords are never stored, logged or displayed. */\n(function () {\n  'use strict';\n\n  var SEARCH_SVG = '<svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M20 20l-3.5-3.5\"/></svg>';\n\n  var EN = {\n    'الموردين': 'Suppliers',\n    'الرصيد': 'Stock',\n    'منخفض': 'Low',\n    'الموردين غير مربوطين بعد': 'Suppliers are not linked yet',\n    'جاري البحث عند الموردين…': 'Searching suppliers…',\n    'عند الموردين': 'at suppliers',\n    'رصيدك الحالي': 'Your current stock',\n    'علبة': 'packs',\n    'الأنسب': 'Best',\n    'متوفر': 'Available',\n    'غير متوفر': 'Out of stock',\n    'أضف لطلبية المورد': 'Add to supplier draft',\n    'تمت الإضافة': 'Added',\n    'بدائل اقترحها المورد (غالباً نفس المادة الفعالة، راجعها)': 'Alternatives suggested by the supplier (usually same active ingredient, review them)',\n    'سعر الصيدلية قبل التوصيل': 'Pharmacy price before delivery',\n    'آخر تحديث': 'Last update',\n    'إغلاق': 'Close',\n    'إدارة الموردين': 'Manage suppliers',\n    'تعذر الاتصال': 'Connection failed',\n    'إضافة مورد': 'Add supplier',\n    'اختار المورد': 'Choose supplier',\n    'الإيميل': 'Email',\n    'كلمة السر': 'Password',\n    'فحص الاتصال': 'Test connection',\n    'حفظ': 'Save',\n    'إلغاء': 'Cancel',\n    'فحص': 'Test',\n    'مربوط': 'Linked',\n    'خطأ': 'Error',\n    'قريباً': 'Soon',\n    'جاهز': 'Ready',\n    'الحساب': 'Account',\n    'كلمة السر بتتحفظ مشفّرة على سيرفر NOVA ومش بتظهر تاني، حتى ليك. تقدر تمسح الربط في أي وقت. النظام بيقرأ الأسعار بس، وما بيطلبش حاجة.': 'The password is stored encrypted on the NOVA server and is never shown again, even to you. You can unlink at any time. The system only reads prices and never orders anything.',\n    'إدارة حسابات الموردين وربطهم بالأسعار.': 'Manage supplier accounts and price links.',\n    'جاري الفحص…': 'Testing…',\n    'جاري الحفظ…': 'Saving…',\n    'خصم عن سعر الجمهور': 'Discount off public price'\n  };\n\n  function isEn() {\n    var c = (document.documentElement.className || '') + ' ' + (document.body ? document.body.className : '');\n    return c.indexOf('lang-en') !== -1;\n  }\n  function tr(ar) {\n    return isEn() && EN[ar] ? EN[ar] : ar;\n  }\n  function esc(s) {\n    return String(s == null ? '' : s).replace(/[&<>\"']/g, function (ch) {\n      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[ch];\n    });\n  }\n  function provider() {\n    return window.NOVA_SUPPLIER_PROVIDER || null;\n  }\n\n  var modelApi = null;\n  import('./worker/procurement/ui-model.js').then(function (m) { modelApi = m; }).catch(function () {});\n\n  var draftStore = null;\n  function draft() {\n    if (!draftStore && modelApi) {\n      try { draftStore = modelApi.createDraftStore(window.localStorage); } catch (e) { draftStore = null; }\n    }\n    return draftStore;\n  }\n\n  function productStockByBarcode(barcode) {\n    var demo = window.NOVA_DEMO;\n    if (!demo || !demo.products) return null;\n    for (var i = 0; i < demo.products.length; i++) {\n      if (String(demo.products[i].barcode) === String(barcode)) return demo.products[i];\n    }\n    return null;\n  }\n\n  /* ---------- modal helpers ---------- */\n  function openModal(cardClass, labelledBy) {\n    closeModal();\n    var d = document.createElement('div');\n    d.className = 'modal-backdrop active';\n    d.id = 'novaSupplierBackdrop';\n    d.style.zIndex = '9300';\n    d.innerHTML = '<div class=\"modal-card ' + cardClass + '\" role=\"dialog\" aria-modal=\"true\"' +\n      (labelledBy ? ' aria-label=\"' + esc(labelledBy) + '\"' : '') + '></div>';\n    d.addEventListener('click', function (e) { if (e.target === d) closeModal(); });\n    document.body.appendChild(d);\n    return d.querySelector('.modal-card');\n  }\n  function closeModal() {\n    var old = document.getElementById('novaSupplierBackdrop');\n    if (old) old.remove();\n  }\n  document.addEventListener('keydown', function (e) {\n    if (e.key === 'Escape' && document.getElementById('novaSupplierBackdrop')) closeModal();\n  });\n\n  /* ---------- lookup popup ---------- */\n  function purchasePrefs() {\n    var defaults = { suppliers: ['aumet', 'pharmaoverseas'], aumetSellers: [] };\n    try { return Object.assign(defaults, JSON.parse(localStorage.getItem('novaPurchasePrefsV1') || '{}')); }\n    catch (e) { return defaults; }\n  }\n  function sellerScopeHtml() {\n    var prefs = purchasePrefs();\n    var enabled = Array.isArray(prefs.suppliers) && prefs.suppliers.indexOf('aumet') !== -1;\n    var count = Array.isArray(prefs.aumetSellers) ? prefs.aumetSellers.length : 0;\n    var message = !enabled ? 'أوميت متوقف في اختيارات الموردين' : !count\n      ? 'أوميت مستبعد من البحث: اختَر مخازنك أولًا على هذا المتصفح'\n      : 'البحث في أوميت داخل ' + count + ' مخزن محدد على هذا المتصفح';\n    return '<div class=\"sp-scope\"><span>' + esc(tr(message)) + '</span> <button type=\"button\" class=\"sp-link\" data-aumet-scope>' + tr('اختيار مخازن أوميت') + '</button></div>';\n  }\n  function bindSellerScope(card, query, stock) {\n    var button = card.querySelector('[data-aumet-scope]');\n    if (button) button.addEventListener('click', function () { openSellerScope(query, stock); });\n  }\n  function openSellerScope(query, stock) {\n    var prefs = purchasePrefs();\n    var selected = (Array.isArray(prefs.aumetSellers) ? prefs.aumetSellers : []).map(String);\n    var card = openModal('ss-card', tr('اختيار مخازن أوميت'));\n    card.innerHTML = '<div class=\"modal-header\"><h3>' + tr('اختيار مخازن أوميت') + '</h3></div><div class=\"ss-body\">' + tr('جاري قراءة المخازن…') + '</div><div class=\"modal-footer\"><button class=\"btn btn-secondary\" data-back>' + tr('إلغاء') + '</button><button class=\"btn btn-primary\" data-save-scope disabled>' + tr('حفظ وإعادة البحث') + '</button></div>';\n    card.querySelector('[data-back]').addEventListener('click', function () { openLookup(query, stock); });\n    provider().listSellers().then(function (r) {\n      if (!document.body.contains(card)) return;\n      var sellers = (r.sellers || []).filter(function (s) { return !s.locked; });\n      var body = card.querySelector('.ss-body');\n      if (!sellers.length) { body.textContent = tr('مخازن حساب أوميت غير متاحة؛ جدّد جلسة المورد ثم حاول تاني. الاختيارات المحفوظة لم تتغير.'); return; }\n      body.innerHTML = '<p>' + tr('اختَر المخازن المسموح البحث فيها. الحفظ يفعّل أوميت على هذا المتصفح.') + '</p>' + sellers.map(function (s) {\n        return '<label style=\"display:flex;align-items:center;gap:10px;min-height:44px\"><input type=\"checkbox\" data-seller-id=\"' + esc(s.id) + '\"' + (selected.indexOf(String(s.id)) !== -1 ? ' checked' : '') + '>' + esc(s.name) + '</label>';\n      }).join('') + '<p class=\"sp-err\" data-scope-error></p>';\n      var save = card.querySelector('[data-save-scope]'); save.disabled = false;\n      save.addEventListener('click', function () {\n        var ids = Array.from(body.querySelectorAll('[data-seller-id]:checked')).map(function (input) { return input.getAttribute('data-seller-id'); });\n        var error = body.querySelector('[data-scope-error]');\n        if (!ids.length) { error.textContent = tr('اختَر مخزنًا واحدًا على الأقل'); return; }\n        // Re-read before saving so days, coverage and other supplier choices survive.\n        var latest = purchasePrefs(); latest.aumetSellers = ids;\n        latest.suppliers = Array.isArray(latest.suppliers) ? latest.suppliers.slice() : [];\n        if (latest.suppliers.indexOf('aumet') === -1) latest.suppliers.push('aumet');\n        try { provider().savePurchasePrefs(latest); }\n        catch (e) { error.textContent = tr('تعذر حفظ الاختيار؛ فعّل تخزين المتصفح ثم حاول تاني'); return; }\n        openLookup(query, stock);\n      });\n    }).catch(function () {\n      if (document.body.contains(card)) card.querySelector('.ss-body').textContent = tr('تعذر قراءة مخازن أوميت؛ الاختيارات المحفوظة لم تتغير. جدّد جلسة المورد ثم حاول تاني.');\n    });\n  }\n  function openLookup(query, stock) {\n    var card = openModal('sp-card', tr('الموردين'));\n    var title = esc(query || '');\n    var head = '<div class=\"modal-header\"><div><h3>' + title + ' ' + tr('عند الموردين') + '</h3>' +\n      (Number.isFinite(stock) ? '<div style=\"font-size:11px;color:var(--text-muted);margin-top:3px\">' + tr('رصيدك الحالي') + ' ' + stock + ' ' + tr('علبة') + '</div>' : '') +\n      '</div></div>';\n    if (!provider()) {\n      card.innerHTML = head + '<div class=\"sp-body\"><div class=\"sp-state\">' + tr('الموردين غير مربوطين بعد') + '</div></div>' +\n        '<div class=\"modal-footer\"><button class=\"btn btn-secondary\" data-close>' + tr('إغلاق') + '</button></div>';\n      bindClose(card);\n      return;\n    }\n    card.innerHTML = head + sellerScopeHtml() + '<div class=\"sp-body\"><div class=\"sp-state\">' + tr('جاري البحث عند الموردين…') + '</div></div>' +\n      '<div class=\"modal-footer\"><span class=\"sp-foot-note\">' + tr('سعر الصيدلية قبل التوصيل') + '</span><button class=\"btn btn-secondary\" data-close>' + tr('إغلاق') + '</button></div>';\n    bindClose(card);\n    bindSellerScope(card, query, stock);\n    provider().search(query, { requestedQty: 1 }).then(function (res) {\n      if (!document.body.contains(card)) return;\n      renderLookup(card, res);\n    }).catch(function () {\n      if (!document.body.contains(card)) return;\n      var body = card.querySelector('.sp-body');\n      if (body) body.innerHTML = '<div class=\"sp-err\">' + tr('تعذر الاتصال') + '</div>';\n    });\n  }\n\n  function bindClose(root) {\n    root.querySelectorAll('[data-close]').forEach(function (b) { b.addEventListener('click', closeModal); });\n    var link = root.querySelector('[data-suppliers]');\n    if (link) link.addEventListener('click', function () { openSuppliersScreen(); });\n  }\n\n  var FORM_AR = { tab: 'أقراص', cap: 'كبسولات', sachet: 'أكياس', supp: 'لبوس', susp: 'معلق', syrup: 'شراب', drops: 'نقط', amp: 'أمبول', vial: 'فيال', cream: 'كريم', gel: 'جل', eff: 'فوار' };\n  var UNIT_AR = { tab: 'قرص', cap: 'كبسولة', sachet: 'كيس', supp: 'لبوسة', amp: 'أمبول', vial: 'فيال', ml: 'مل', drops: 'نقطة', bottle: 'زجاجة', strip: 'شريط' };\n  function extractOfferSpecs(o) {\n    o = o || {};\n    var name = String(o.productName || '');\n    var sm = name.match(/(\\d+(?:\\.\\d+)?(?:\\s*\\/\\s*\\d+(?:\\.\\d+)?)?)\\s*(mcg|mg|gm|g|iu|ml|%)/i);\n    var strength = o.strength ? String(o.strength) : (sm ? sm[1].replace(/\\s+/g, '') + ' ' + sm[2].toLowerCase() : '');\n    var fm = name.match(/\\b(tablets?|tabs?|capsules?|caps?|sachets?|supp|susp|syrup|syp|drops|amps?|vials?|cream|gel|eff)\\b/i);\n    var fk = fm ? fm[1].toLowerCase().replace(/s$/, '').replace(/^tablet$/, 'tab').replace(/^capsule$/, 'cap').replace(/^syp$/, 'syrup') : '';\n    var form = o.form ? (FORM_AR[String(o.form).toLowerCase()] || String(o.form)) : (FORM_AR[fk] || '');\n    var masked = sm ? name.replace(sm[0], ' ') : name;\n    var pm = masked.match(/(\\d+)\\s*(tablets?|tabs?|capsules?|caps?|sachets?|supp|amps?|vials?|ml|drops|bottle|strip)\\b/i);\n    var pk = pm ? pm[2].toLowerCase().replace(/s$/, '').replace(/^tablet$/, 'tab').replace(/^capsule$/, 'cap') : '';\n    var pack = o.packSize ? String(o.packSize) : (pm ? pm[1] + ' ' + (UNIT_AR[pk] || pk) : '');\n    var stamp = Date.parse(o.lastUpdated || '');\n    var date = isFinite(stamp) ? new Date(stamp).toISOString().slice(0, 10) : '';\n    return { strength: strength, form: form, packSize: pack, date: date };\n  }\n\n  function rowHtml(row, showSeller, groupMode) {\n    var meta = [];\n    if (groupMode && showSeller && row.sellerName) meta.push('<span>' + esc(row.sellerName) + '</span>');\n    if (!groupMode) meta.push('<span>' + esc(row.supplierName) + '</span>');\n    if (row.strength) meta.push('<span>' + esc(row.strength) + '</span>');\n    if (row.form) meta.push('<span>' + esc(row.form) + '</span>');\n    if (row.packSize) meta.push('<span>' + esc(row.packSize) + '</span>');\n    if (row.unitPriceLabel) meta.push('<span>' + esc(row.unitPriceLabel) + '</span>');\n    if (row.date) meta.push('<span>' + esc(row.date) + '</span>');\n    var tag = row.best ? '<span class=\"sp-tag t-best\">' + tr('الأنسب') + '</span>'\n      : row.eligible ? '<span class=\"sp-tag t-ok\">' + esc(row.stockLabel) + '</span>'\n      : '<span class=\"sp-tag t-off\">' + esc(row.stockLabel) + '</span>';\n    meta.push(tag);\n    var disc = Number.isFinite(row.discountPct)\n      ? '<span class=\"sp-disc\">' + tr('خصم عن سعر الجمهور') + ' ' + row.discountPct + '%</span>' : '';\n    var pub = Number.isFinite(row.publicPrice) ? '<span class=\"sp-pub\">' + row.publicPrice + '</span>' : '';\n    var price = Number.isFinite(row.packPrice)\n      ? '<div class=\"sp-p\">' + Number(row.packPrice).toFixed(2) + ' <span style=\"font:11px var(--font);color:var(--text-muted)\">ج.م</span></div>' : '';\n    return '<div class=\"sp-row' + (row.best ? ' best' : '') + (row.eligible ? '' : ' off') + '\" data-key=\"' + esc(row.key) + '\">' +\n      '<div><div class=\"sp-name\">' + esc(row.productName) + '</div><div class=\"sp-meta\">' + meta.join('') + '</div></div>' +\n      '<div class=\"sp-price\"><div>' + pub + disc + '</div>' + price + '</div>' +\n      '<div class=\"sp-add\"><div class=\"sp-qty\"><button class=\"btn btn-secondary\" data-dec>−</button><b>1</b><button class=\"btn btn-secondary\" data-inc>+</button></div>' +\n      '<button class=\"btn btn-primary\" data-add>' + tr('أضف لطلبية المورد') + '</button></div></div>';\n  }\n\n  function groupsHtml(groups, rowsByKey) {\n    var multi = groups.length > 1 || groups.some(function (g) { return g.rows.some(function (r) { return r.sellerName; }); });\n    var html = '';\n    groups.forEach(function (g) {\n      if (multi) html += '<div class=\"sp-group-head\">' + esc(g.supplierName) + '</div>';\n      g.rows.forEach(function (row) {\n        rowsByKey[row.key] = row;\n        html += rowHtml(row, !!row.sellerName, multi);\n      });\n    });\n    return html;\n  }\n\n  function renderLookup(card, res) {\n    var body = card.querySelector('.sp-body');\n    if (!body || !modelApi) return;\n    // Re-read the shared saved selection at render time too, including injected providers.\n    var allowed=[];try{allowed=JSON.parse(localStorage.getItem('novaPurchasePrefsV1')||'{}').aumetSellers||[];}catch(e){}\n    res=JSON.parse(JSON.stringify(res));\n    var specsByKey = {};\n    (res.results||[]).forEach(function(r){\n      r.offers=(r.offers||[]).filter(function(row){\n        var o=row.offer||row;\n        var k=String(o.supplierId||'')+'::'+String(o.sellerId==null?'':o.sellerId)+'::'+String(o.productName||'');\n        specsByKey[k]=extractOfferSpecs(o);\n        return o.supplierId!=='aumet'||allowed.map(String).indexOf(String(o.sellerId))!==-1;\n      });\n      r.best=null;\n    });\n    var model = modelApi.buildLookupModel(res, { requestedQty: 1 });\n    function enrichGroups(gs) {\n      (gs || []).forEach(function (g) {\n        (g.rows || []).forEach(function (row) { Object.assign(row, specsByKey[row.key] || extractOfferSpecs(row)); });\n      });\n    }\n    enrichGroups(model.groups);\n    (model.altGroups || []).forEach(function (a) { enrichGroups(a.groups); });\n    var rowsByKey = {};\n    var html = groupsHtml(model.groups, rowsByKey);\n    (res.suppliers || []).forEach(function (s) {\n      if (s && (s.state === 'error' || s.state === 'expired')) {\n        var msg = s.state === 'expired' ? (s.message || tr('الجلسة انتهت، سجّل دخول المورد')) : (s.message || tr('تعذر الاتصال'));\n        html += '<div class=\"sp-err\">' + esc(s.name || s.id) + ': ' + esc(msg) + '</div>';\n      }\n    });\n    model.altGroups.forEach(function (alt, i) {\n      html += '<div class=\"sp-sec\">' + (i === 0 ? esc(model.suggestionsNote || '') : '') + '</div>';\n      html += groupsHtml(alt.groups, rowsByKey);\n    });\n    if (!Object.keys(rowsByKey).length) html += '<div class=\"sp-state\">' + tr('لا توجد عروض من المخازن المحددة؛ راجع إعدادات المشتريات') + '</div>';\n    body.innerHTML = html;\n\n    var foot = card.querySelector('.modal-footer');\n    if (foot) {\n      var note = tr('سعر الصيدلية قبل التوصيل');\n      if (res.fetchedAt) {\n        var t = new Date(res.fetchedAt);\n        if (!isNaN(t)) note += ' · ' + tr('آخر تحديث') + ' ' + t.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });\n      }\n      foot.innerHTML = '<span class=\"sp-foot-note\">' + note + '</span>' +\n        '<button class=\"sp-link\" data-suppliers>' + tr('إدارة الموردين') + '</button>' +\n        '<button class=\"btn btn-secondary\" data-close>' + tr('إغلاق') + '</button>';\n      bindClose(card);\n    }\n\n    body.querySelectorAll('.sp-row').forEach(function (el) {\n      var row = rowsByKey[el.getAttribute('data-key')];\n      if (!row) return;\n      var qtyEl = el.querySelector('.sp-qty b');\n      var qty = 1;\n      el.querySelector('[data-dec]').addEventListener('click', function () { qty = Math.max(1, qty - 1); qtyEl.textContent = qty; });\n      el.querySelector('[data-inc]').addEventListener('click', function () { qty = Math.min(999, qty + 1); qtyEl.textContent = qty; });\n      el.querySelector('[data-add]').textContent=tr('إضافة لسلة المورد');\n      el.querySelector('[data-add]').disabled=!row.eligible;\n      el.querySelector('[data-add]').addEventListener('click', async function (e) {\n        var b=e.currentTarget;if(b.disabled)return;\n        if(qty<Number(row.minimumOrderQuantity||1)||(Number.isFinite(row.availableQuantity)&&qty>row.availableQuantity)){\n          b.textContent=tr('راجع الكمية المتاحة والحد الأدنى');return;\n        }\n        b.disabled=true;b.textContent=tr('جارٍ مراجعة سلة المورد…');\n        try {\n          var r=await provider().addToSupplierCart({supplierId:row.supplierId,productId:row.supplierProductId,sellerId:row.sellerId,quantity:qty,price:row.unitPrice,query:row.productName},function(p){return window.confirm(row.supplierName+' — '+(row.sellerName||'')+'\\n'+row.productName+'\\n'+tr('في السلة')+': '+p.before+' + '+p.quantity+' = '+p.target+'\\n'+tr('تأكيد الإضافة الفعلية لسلة المورد؟'));});\n          if(r.ok&&r.state==='verified') {b.textContent=tr('تم التأكد من الإضافة عند المورد');return;}\n          if(r.state==='cancelled'){b.textContent=tr('إضافة لسلة المورد');b.disabled=false;return;}\n          throw new Error(r.error||'cart-readback-unavailable');\n        } catch(error) {\n          b.disabled=false;b.textContent=tr('لم تتأكد الإضافة — إعادة التحقق');\n          var note=el.querySelector('.sp-cart-error');if(!note){note=document.createElement('p');note.className='sp-cart-error sp-err';el.appendChild(note);}\n          note.textContent=tr(error.message==='cart-storage-unavailable'?'فعّل تخزين المتصفح لحفظ حالة الإضافة قبل التنفيذ':error.message==='cart-session-required'?'جلسة المورد تحتاج تجديدًا يدعم السلة':error.message==='cart-not-supported'?'ربط سلة هذا المورد غير جاهز بعد؛ لم تتم الإضافة':'تعذر تأكيد الإضافة؛ راجع سلة المورد قبل محاولة جديدة');\n        }\n      });\n    });\n  }\n\n  /* ---------- suppliers screen ---------- */\n  function stateChip(state) {\n    if (state === 'ok') return '<span class=\"ss-tag ss-ok\"><span class=\"ss-dot\"></span>' + tr('مربوط') + '</span>';\n    if (state === 'error') return '<span class=\"ss-tag ss-err\"><span class=\"ss-dot\"></span>' + tr('خطأ') + '</span>';\n    return '<span class=\"ss-tag ss-off\">' + tr('قريباً') + '</span>';\n  }\n\n  function openSuppliersScreen() {\n    var card = openModal('ss-card', tr('الموردين'));\n    var p = provider();\n    var head = '<div class=\"modal-header\"><h3>' + tr('الموردين') + '</h3><button class=\"btn btn-secondary\" data-close>' + tr('إغلاق') + '</button></div>';\n    if (!p) {\n      card.innerHTML = head + '<div class=\"ss-body\"><div class=\"sp-state\">' + tr('الموردين غير مربوطين بعد') + '</div></div>' +\n        '<div class=\"modal-footer\"><button class=\"btn btn-secondary\" data-close>' + tr('إغلاق') + '</button></div>';\n      bindClose(card);\n      return;\n    }\n    card.innerHTML = head + '<div class=\"ss-body\"><div class=\"sp-state\">' + tr('جاري البحث عند الموردين…') + '</div></div>' +\n      '<div class=\"modal-footer\"><button class=\"btn btn-primary\" data-add-supplier>+ ' + tr('إضافة مورد') + '</button></div>';\n    bindClose(card);\n    p.listSuppliers().then(function (list) {\n      if (!document.body.contains(card)) return;\n      var body = card.querySelector('.ss-body');\n      body.innerHTML = (list || []).map(function (s) {\n        var initials = String(s.name || s.id || '?').replace(/[^A-Za-z]/g, '').slice(0, 2).toUpperCase() || '··';\n        var sub = s.account ? tr('الحساب') + ': ' + esc(s.account) : (s.message ? esc(s.message) : '');\n        return '<div class=\"ss-row\" data-id=\"' + esc(s.id) + '\"><div class=\"ss-logo\">' + esc(initials) + '</div>' +\n          '<div class=\"ss-grow\"><div class=\"ss-name\">' + esc(s.name || s.id) + '</div><div class=\"ss-sub\">' + sub + '</div></div>' +\n          stateChip(s.state) +\n          (s.state !== 'off' ? '<button class=\"btn btn-secondary\" data-test>' + tr('فحص') + '</button>' : '') +\n          '</div>';\n      }).join('') || '<div class=\"sp-state\">' + tr('لا توجد عروض من المخازن المحددة؛ راجع إعدادات المشتريات') + '</div>';\n      body.querySelectorAll('[data-test]').forEach(function (b) {\n        b.addEventListener('click', function () {\n          var id = b.closest('.ss-row').getAttribute('data-id');\n          b.disabled = true;\n          p.testSupplier(id).then(function (r) {\n            b.disabled = false;\n            var chip = b.closest('.ss-row').querySelector('.ss-tag');\n            if (chip) chip.outerHTML = stateChip(r && r.ok ? 'ok' : 'error');\n            if (r && r.message) b.closest('.ss-row').querySelector('.ss-sub').textContent = r.message;\n          }).catch(function () { b.disabled = false; });\n        });\n      });\n    }).catch(function () {});\n    var addBtn = card.querySelector('[data-add-supplier]');\n    if (addBtn) addBtn.addEventListener('click', function () { openAddSupplier(card, p); });\n  }\n\n  function openAddSupplier(card, p) {\n    p.listSuppliers().then(function (list) {\n      if (!document.body.contains(card)) return;\n      var available = (list || []).filter(function (s) { return s.available; });\n      var selected = available.length ? available[0].id : null;\n      card.querySelector('.modal-header h3').textContent = tr('إضافة مورد');\n      var body = card.querySelector('.ss-body');\n      body.innerHTML =\n        '<div><span class=\"ss-lbl\">' + tr('اختار المورد') + '</span><div class=\"ss-sel\">' +\n          (list || []).map(function (s) {\n            var cls = s.available ? (s.id === selected ? 'ss-opt on' : 'ss-opt') : 'ss-opt dis';\n            var small = s.available ? tr('جاهز') : tr('قريباً');\n            return '<div class=\"' + cls + '\" data-id=\"' + esc(s.id) + '\">' + esc(s.name || s.id) + '<small>' + small + '</small></div>';\n          }).join('') + '</div></div>' +\n        '<div><span class=\"ss-lbl\">' + tr('الإيميل') + '</span><input class=\"ss-in\" dir=\"ltr\" type=\"email\" autocomplete=\"off\"></div>' +\n        '<div><span class=\"ss-lbl\">' + tr('كلمة السر') + '</span><input class=\"ss-in\" dir=\"ltr\" type=\"password\" autocomplete=\"off\"></div>' +\n        '<div class=\"ss-msg\"></div>' +\n        '<div class=\"ss-note\">' + tr('كلمة السر بتتحفظ مشفّرة على سيرفر NOVA ومش بتظهر تاني، حتى ليك. تقدر تمسح الربط في أي وقت. النظام بيقرأ الأسعار بس، وما بيطلبش حاجة.') + '</div>';\n      card.querySelector('.modal-footer').innerHTML =\n        '<button class=\"btn btn-secondary\" data-back>' + tr('إلغاء') + '</button>' +\n        '<button class=\"btn btn-secondary\" data-check>' + tr('فحص الاتصال') + '</button>' +\n        '<button class=\"btn btn-primary\" data-save>' + tr('حفظ') + '</button>';\n\n      body.querySelectorAll('.ss-opt').forEach(function (opt) {\n        if (opt.classList.contains('dis')) return;\n        opt.addEventListener('click', function () {\n          body.querySelectorAll('.ss-opt').forEach(function (o) { o.classList.remove('on'); });\n          opt.classList.add('on');\n          selected = opt.getAttribute('data-id');\n        });\n      });\n\n      var emailIn = body.querySelector('input[type=email]');\n      var passIn = body.querySelector('input[type=password]');\n      var msg = body.querySelector('.ss-msg');\n      function connect() {\n        var cred = { supplierId: selected, email: emailIn.value.trim(), password: passIn.value };\n        passIn.value = '';\n        if (!cred.supplierId) return Promise.resolve({ ok: false, message: tr('اختار المورد') });\n        return p.connectSupplier(cred);\n      }\n      card.querySelector('[data-back]').addEventListener('click', openSuppliersScreen);\n      card.querySelector('[data-check]').addEventListener('click', function () {\n        msg.textContent = tr('جاري الفحص…');\n        connect().then(function (r) { msg.textContent = (r && r.message) || (r && r.ok ? tr('مربوط') : tr('خطأ')); })\n          .catch(function () { msg.textContent = tr('تعذر الاتصال'); });\n      });\n      card.querySelector('[data-save]').addEventListener('click', function () {\n        msg.textContent = tr('جاري الحفظ…');\n        connect().then(function (r) {\n          msg.textContent = (r && r.message) || (r && r.ok ? tr('مربوط') : tr('خطأ'));\n          if (r && r.ok) setTimeout(openSuppliersScreen, 600);\n        }).catch(function () { msg.textContent = tr('تعذر الاتصال'); });\n      });\n    }).catch(function () {});\n  }\n\n  /* ---------- row unit inside suggestion rows ---------- */\n  function decorateRow(item) {\n    if (item.querySelector('.su')) return;\n    if (item.closest('#suggestionsBox') === null) return;\n    var tag = item.querySelector('.sugg-tag');\n    if (!tag) return;\n    var prod = productStockByBarcode(tag.textContent.trim());\n    if (!prod) return;\n    var nameEl = item.querySelector('.sugg-primary');\n    var name = nameEl ? nameEl.textContent.trim() : '';\n    var known = typeof prod.stock === 'number' && Number.isFinite(prod.stock);\n    var st = !known ? { tone: 'unknown', label: '' }\n      : modelApi ? modelApi.stockUnitState(prod.stock) : { tone: prod.stock < 30 ? 'low' : 'ok', label: '' };\n    var low = known && st.tone === 'low';\n    var w = document.createElement('div');\n    w.className = 'su ' + (!known ? 'su-ok su-unknown' : low ? 'su-low' : 'su-ok');\n    var iconBtn = '<button type=\"button\" class=\"su-btn icon\" title=\"' + tr('الموردين') + '\" aria-label=\"' + tr('الموردين') + '\">' + SEARCH_SVG + '</button>';\n    w.innerHTML = (known\n      ? '<span class=\"su-stock\"><span class=\"su-dot\"></span><small>' + tr('الرصيد') + '</small><b>' + prod.stock + '</b>' +\n        (low ? '<small>· ' + tr('منخفض') + '</small>' : '') + '</span>'\n      : '') +   // unknown stock: no green dot and no «غير متوفر» (it contradicted «الرصيد غير معروف» on the same row); the suppliers button stays\n      (low ? '<button type=\"button\" class=\"su-btn\">' + SEARCH_SVG + tr('الموردين') + '</button>' : iconBtn);\n    w.querySelector('.su-btn').addEventListener('click', function (e) {\n      e.stopPropagation();\n      e.preventDefault();\n      openLookup(name, known ? prod.stock : undefined);\n    });\n    item.insertBefore(w, item.lastElementChild);\n  }\n\n  function decorateEmpty(box) {\n    var kids = box.querySelectorAll('div');\n    for (var i = 0; i < kids.length; i++) {\n      var t = kids[i].textContent || '';\n      if ((t.indexOf('No products found matching') !== -1 || t.indexOf('لا توجد منتجات مطابقة') !== -1) && !kids[i].querySelector('.su-empty')) {\n        var holder = document.createElement('div');\n        holder.className = 'su-empty';\n        holder.innerHTML = '<button type=\"button\" class=\"su-btn\">' + SEARCH_SVG + tr('الموردين') + '</button>';\n        holder.querySelector('.su-btn').addEventListener('click', function (e) {\n          e.stopPropagation();\n          e.preventDefault();\n          var input = document.getElementById('mainSearchInput');\n          openLookup(input ? input.value.trim() : '', null);\n        });\n        kids[i].appendChild(holder);\n      }\n    }\n  }\n\n  function scanSuggestions() {\n    var box = document.getElementById('suggestionsBox');\n    if (!box) return;\n    box.querySelectorAll('.suggestion-item').forEach(decorateRow);\n    decorateEmpty(box);\n  }\n\n  /* ---------- settings entry ---------- */\n  function decorateSettings() {\n    var grid = document.querySelector('.nova-settings-grid');\n    if (!grid || grid.querySelector('[data-su-settings]')) return;\n    var card = document.createElement('div');\n    card.className = 'nova-setting-card';\n    card.setAttribute('data-su-settings', '1');\n    card.innerHTML = '<h3>' + tr('الموردين') + '</h3><p>' + tr('إدارة حسابات الموردين وربطهم بالأسعار.') + '</p>' +\n      '<button type=\"button\" class=\"nova-page-btn\">' + tr('إدارة الموردين') + '</button>';\n    card.querySelector('button').addEventListener('click', openSuppliersScreen);\n    grid.appendChild(card);\n  }\n\n  function scanAll() {\n    scanSuggestions();\n    decorateSettings();\n  }\n\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', init);\n  } else {\n    init();\n  }\n  function init() {\n    scanAll();\n    new MutationObserver(function () { scanAll(); })\n      .observe(document.body, { childList: true, subtree: true });\n  }\n})();\n\n","type":"application/javascript"},"/icon.svg":{"body":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 192 192\"><rect width=\"192\" height=\"192\" rx=\"40\" fill=\"#0d141e\"/><path d=\"M45 127V65h20l62 64V65h20v62h-20L65 64v63z\" fill=\"#60c7f4\"/><circle cx=\"145\" cy=\"46\" r=\"9\" fill=\"#b6a37e\"/></svg>","type":"image/svg+xml"},"/bi-dictionary.js":{"body":"/* NOVA Rx — BI-01 indicator dictionary (pure logic, no DOM, no network).\n   ONE source of definitions and formulas for POS, dashboard and exports. Money = integer piastres.\n   Works as a <script> (window.NovaBI) and in Node (module.exports). */\n(function (root) {\n  'use strict';\n  function isInt(n) { return typeof n === 'number' && isFinite(n) && Math.floor(n) === n; }\n  function fail(code) { var e = new Error(code); e.code = code; throw e; }\n  function int(n) { if (n == null) return 0; if (!isInt(n)) fail('bad-integer'); return n; }\n\n  var INDICATORS = {\n    gross:    { ar: 'الإجمالي',        en: 'Gross',    unit: 'piastres', rule: 'sum(qty × list price) of sold lines, before discount and returns' },\n    discount: { ar: 'الخصم',           en: 'Discount', unit: 'piastres', rule: 'sum of line and invoice discounts, always >= 0' },\n    return:   { ar: 'المرتجع',         en: 'Return',   unit: 'piastres', rule: 'sum of refunded amounts net of their discount share, always >= 0' },\n    net:      { ar: 'الصافي',          en: 'Net',      unit: 'piastres', rule: 'gross − discount − return' },\n    cost:     { ar: 'التكلفة',         en: 'Cost',     unit: 'piastres', rule: 'sum(qty × unit cost) of sold lines minus cost of returned units' },\n    margin:   { ar: 'هامش الربح',      en: 'Margin',   unit: 'piastres', rule: 'net − cost' },\n    marginPct:{ ar: 'نسبة الهامش',     en: 'Margin %', unit: 'bps',      rule: 'round(margin × 10000 / net) half up in basis points; 0 when net <= 0' },\n    visits:   { ar: 'الزيارات',        en: 'Visits',   unit: 'count',    rule: 'count of distinct non-cancelled invoices (one invoice = one visit)' }\n  };\n  var ORDER = ['gross', 'discount', 'return', 'net', 'cost', 'margin', 'marginPct', 'visits'];\n\n  function divRound(a, b) {\n    var s = a < 0 ? -1 : 1, x = Math.abs(a), q = Math.floor(x / b);\n    if ((x - q * b) * 2 >= b) q += 1;\n    return s * q;\n  }\n\n  /* totals: {gross, discount, return, cost, visits} (integers) -> all indicators. */\n  function compute(t) {\n    t = t || {};\n    var gross = int(t.gross), discount = int(t.discount), ret = int(t['return']), cost = int(t.cost), visits = int(t.visits);\n    if (gross < 0 || discount < 0 || ret < 0 || cost < 0 || visits < 0) fail('negative-input');\n    var net = gross - discount - ret, margin = net - cost;\n    return { gross: gross, discount: discount, 'return': ret, net: net, cost: cost, margin: margin,\n      marginPct: net > 0 ? divRound(margin * 10000, net) : 0, visits: visits };\n  }\n\n  /* invoices: [{status, lines:[{qty, price, cost, discount}], discount, returns:[{amount, cost}]}] */\n  function fromInvoices(invoices) {\n    var t = { gross: 0, discount: 0, 'return': 0, cost: 0, visits: 0 };\n    (invoices || []).forEach(function (inv) {\n      if (!inv || inv.status === 'cancelled') return;\n      t.visits += 1;\n      (inv.lines || []).forEach(function (l) {\n        t.gross += int(l.qty) * int(l.price); t.cost += int(l.qty) * int(l.cost); t.discount += int(l.discount);\n      });\n      t.discount += int(inv.discount);\n      (inv.returns || []).forEach(function (r) { t['return'] += int(r.amount); t.cost -= int(r.cost); });\n    });\n    return compute(t);\n  }\n\n  /* Display / export helpers share the same labels and formatting. */\n  function label(key, lang) { var d = INDICATORS[key]; if (!d) fail('unknown-indicator'); return lang === 'en' ? d.en : d.ar; }\n  function fmt(key, v) {\n    if (!INDICATORS[key]) fail('unknown-indicator');\n    var u = INDICATORS[key].unit;\n    if (u === 'count') return String(v);\n    var neg = v < 0, a = Math.abs(v);\n    if (u === 'bps') return (neg ? '-' : '') + Math.floor(a / 100) + '.' + ('0' + (a % 100)).slice(-2) + '%';\n    return (neg ? '-' : '') + Math.floor(a / 100) + '.' + ('0' + (a % 100)).slice(-2);\n  }\n  function toRows(result, lang) {\n    return ORDER.map(function (k) { return { key: k, label: label(k, lang), value: result[k], text: fmt(k, result[k]) }; });\n  }\n  function toCsv(result, lang) {\n    return '﻿' + 'indicator,value\\r\\n' + toRows(result, lang).map(function (r) { return r.label + ',' + r.text; }).join('\\r\\n') + '\\r\\n';\n  }\n\n  var api = { INDICATORS: INDICATORS, ORDER: ORDER, compute: compute, fromInvoices: fromInvoices, label: label, fmt: fmt, toRows: toRows, toCsv: toCsv };\n  if (typeof module !== 'undefined' && module.exports) module.exports = api; else root.NovaBI = api;\n})(typeof window !== 'undefined' ? window : globalThis);\n","type":"application/javascript"},"/credit-ledger.js":{"body":"/* NOVA Rx — CRM-02 local credit (آجل) ledger (pure logic, no DOM, no network, frontend/local only).\n   Append-only movements per customer, amounts in integer piastres internally (API takes/returns pounds):\n     opening (opening balance) | charge (credit sale, id = sale id, idempotent) | collection (partial/full, FIFO over open charges, receipt no.)\n     | reversal (cancels one earlier movement; nothing is ever deleted or edited).\n   Credit limit per customer, due dates, aging buckets, and reconcile() against the local sales ledger (novaSales.list()).\n   Works as a <script> (window.NovaCredit) and in Node (module.exports). Not wired to a screen yet. */\n(function (root) {\n  'use strict';\n\n  function fail(code) { var e = new Error(code); e.code = code; throw e; }\n  function copy(o) { return JSON.parse(JSON.stringify(o)); }\n  function cents(n) {\n    if (typeof n !== 'number' || !isFinite(n) || n <= 0) fail('bad-amount');\n    var c = Math.round(n * 100);\n    if (Math.abs(c / 100 - n) > 1e-9) fail('bad-amount');\n    return c;\n  }\n  function pounds(c) { return c / 100; }\n  var DAY = 86400000;\n\n  /* opts: { now(): ms, defaultTermDays: 30 } */\n  function createCreditLedger(storage, key, opts) {\n    key = key || 'nova.credit';\n    opts = opts || {};\n    var now = opts.now || function () { return Date.now(); };\n    var termDays = opts.defaultTermDays == null ? 30 : opts.defaultTermDays;\n\n    function load() {\n      var raw = storage.getItem(key);\n      if (!raw) return { limits: {}, moves: [], receiptSeq: 0 };\n      var s;\n      try { s = JSON.parse(raw); } catch (e) { fail('ledger-corrupt'); }\n      if (!s || typeof s !== 'object' || !Array.isArray(s.moves) || !s.limits) fail('ledger-corrupt');\n      return s;\n    }\n    function save(s) {\n      try { storage.setItem(key, JSON.stringify(s)); } catch (e) { fail('ledger-write-failed'); }\n    }\n    function cust(id) { if (typeof id !== 'string' || !id) fail('missing-customer'); return id; }\n    function byId(s, id) { for (var i = 0; i < s.moves.length; i++) if (s.moves[i].id === id) return s.moves[i]; return null; }\n    function reversed(s, id) { return s.moves.some(function (m) { return m.type === 'reversal' && m.target === id; }); }\n    function liveAlloc(s, chargeId) {\n      var t = 0;\n      s.moves.forEach(function (m) {\n        if (m.type !== 'collection' || reversed(s, m.id)) return;\n        m.allocations.forEach(function (a) { if (a.chargeId === chargeId) t += a.cents; });\n      });\n      return t;\n    }\n    /* open debts of one customer, oldest due first: [{id, due, at, cents (original), open (remaining)}] */\n    function openDebts(s, c) {\n      return s.moves.filter(function (m) { return m.customerId === c && (m.type === 'charge' || m.type === 'opening') && !reversed(s, m.id); })\n        .map(function (m) { return { id: m.id, at: m.at, due: m.due, cents: m.cents, open: m.cents - liveAlloc(s, m.id), ref: m.ref }; })\n        .filter(function (d) { return d.open > 0; })\n        .sort(function (a, b) { return a.due - b.due || a.at - b.at; });\n    }\n    function balanceC(s, c) { return openDebts(s, c).reduce(function (t, d) { return t + d.open; }, 0); }\n    /* S2-05: a random suffix keeps ids unique across devices (old ids stay valid). */\n    function rand6() {\n      var s = Math.random().toString(36).slice(2) + Math.random().toString(36).slice(2);\n      return (s + '000000').slice(0, 6);\n    }\n    function nextId(s, p) { return p + '-' + (s.moves.length + 1) + '-' + rand6(); }\n\n    function setLimit(customerId, limit) {\n      var s = load(); cust(customerId);\n      if (limit === null) delete s.limits[customerId];\n      else { if (typeof limit !== 'number' || !isFinite(limit) || limit < 0) fail('bad-limit'); s.limits[customerId] = Math.round(limit * 100); }\n      save(s);\n    }\n    function limitOf(customerId) { var l = load().limits[customerId]; return l == null ? null : pounds(l); }\n\n    /* Opening balance carried over from the paper book. One per customer (a second one is a mistake: reverse the first). */\n    function openingBalance(customerId, amount, o) {\n      o = o || {}; cust(customerId); var c = cents(amount), s = load(), at = o.at == null ? now() : o.at;\n      var dup = s.moves.some(function (m) { return m.type === 'opening' && m.customerId === customerId && !reversed(s, m.id); });\n      if (dup) fail('opening-exists');\n      var m = { id: nextId(s, 'op'), type: 'opening', customerId: customerId, cents: c, at: at, due: o.due == null ? at : o.due, note: o.note || '' };\n      s.moves.push(m); save(s); return copy(m);\n    }\n\n    /* Credit sale. id = the sale id (idempotent: same id returns the stored charge). Refuses past the limit unless o.override. */\n    function charge(o) {\n      if (!o || typeof o.id !== 'string' || !o.id) fail('missing-key');\n      cust(o.customerId); var c = cents(o.amount), s = load(), ex = byId(s, 'ch-' + o.id);\n      if (ex) return copy(ex);\n      var lim = s.limits[o.customerId];\n      if (lim != null && !o.override && balanceC(s, o.customerId) + c > lim) fail('over-limit');\n      var at = o.at == null ? now() : o.at;\n      var m = { id: 'ch-' + o.id, type: 'charge', ref: o.id, customerId: o.customerId, cents: c, at: at, due: o.due == null ? at + termDays * DAY : o.due, override: !!o.override };\n      s.moves.push(m); save(s); return copy(m);\n    }\n\n    /* Collection (partial or full), allocated to the oldest due debts first. Cannot exceed the balance. Returns the receipt. */\n    function collect(o) {\n      if (!o || typeof o.id !== 'string' || !o.id) fail('missing-key');\n      cust(o.customerId); var c = cents(o.amount), s = load(), ex = byId(s, 'co-' + o.id);\n      if (ex) return receipt(ex);\n      var debts = openDebts(s, o.customerId), bal = debts.reduce(function (t, d) { return t + d.open; }, 0);\n      if (c > bal) fail('exceeds-balance');\n      var left = c, allocs = [];\n      debts.forEach(function (d) { if (left <= 0) return; var a = Math.min(left, d.open); allocs.push({ chargeId: d.id, cents: a }); left -= a; });\n      s.receiptSeq += 1;\n      var m = { id: 'co-' + o.id, type: 'collection', customerId: o.customerId, cents: c, at: o.at == null ? now() : o.at, allocations: allocs,\n        receiptNo: 'RC-' + String(s.receiptSeq).padStart(6, '0'), method: o.method || 'cash' };\n      s.moves.push(m); save(s); return receipt(m, bal - c);\n    }\n    function receipt(m, after) {\n      if (after == null) { var s = load(); after = balanceC(s, m.customerId); }\n      return { receiptNo: m.receiptNo, customerId: m.customerId, amount: pounds(m.cents), at: m.at, method: m.method, id: m.id,\n        allocations: m.allocations.map(function (a) { return { chargeId: a.chargeId, amount: pounds(a.cents) }; }), balanceAfter: pounds(after) };\n    }\n\n    /* Reversal of one earlier movement. A charge/opening with live collections against it must have those reversed first. Idempotent. */\n    function reverse(moveId, reason) {\n      var s = load(), m = byId(s, moveId);\n      if (!m) fail('unknown-movement');\n      if (m.type === 'reversal') fail('cannot-reverse-reversal');\n      if (reversed(s, moveId)) return copy(s.moves.filter(function (r) { return r.type === 'reversal' && r.target === moveId; })[0]);\n      if (!reason || typeof reason !== 'string') fail('reason-required');\n      if ((m.type === 'charge' || m.type === 'opening') && liveAlloc(s, moveId) > 0) fail('has-collections');\n      var r = { id: nextId(s, 'rv'), type: 'reversal', target: moveId, customerId: m.customerId, cents: m.cents, at: now(), reason: reason };\n      s.moves.push(r); save(s); return copy(r);\n    }\n\n    function balance(customerId) { return pounds(balanceC(load(), cust(customerId))); }\n\n    /* Aging at asOf: current (not yet due) | d1_30 | d31_60 | d61_90 | d90_plus (days past due). */\n    function aging(customerId, asOf) {\n      var s = load(), t = asOf == null ? now() : asOf, b = { current: 0, d1_30: 0, d31_60: 0, d61_90: 0, d90_plus: 0 };\n      openDebts(s, cust(customerId)).forEach(function (d) {\n        var days = Math.floor((t - d.due) / DAY);\n        var k = days <= 0 ? 'current' : days <= 30 ? 'd1_30' : days <= 60 ? 'd31_60' : days <= 90 ? 'd61_90' : 'd90_plus';\n        b[k] += d.open;\n      });\n      var out = { total: 0 };\n      Object.keys(b).forEach(function (k) { out[k] = pounds(b[k]); out.total += b[k]; });\n      out.total = pounds(out.total); return out;\n    }\n\n    function statement(customerId) {\n      var s = load(); cust(customerId);\n      return s.moves.filter(function (m) { return m.customerId === customerId; }).map(function (m) {\n        var o = copy(m); o.amount = pounds(m.cents); delete o.cents; o.reversed = m.type !== 'reversal' && reversed(s, m.id); return o;\n      });\n    }\n    function customers() {\n      var s = load(), seen = {};\n      s.moves.forEach(function (m) { seen[m.customerId] = 1; });\n      return Object.keys(seen).map(function (c) { return { customerId: c, balance: pounds(balanceC(s, c)) }; });\n    }\n    function totalOutstanding() { return customers().reduce(function (t, c) { return Math.round((t + c.balance) * 100) / 100; }, 0); }\n\n    /* Reconcile with the local sales ledger. sales: novaSales.list() rows { id, customerId, credit, ... }.\n       Every credit sale must have exactly one live charge of the same amount; every live charge must have a sale; and the\n       sum of customer balances must equal charges + openings - collections. Never changes anything. */\n    function reconcile(sales) {\n      var s = load(), diffs = [], bySale = {};\n      (sales || []).forEach(function (x) {\n        var cr = Math.round((Number(x && x.credit) || 0) * 100);\n        if (x && x.id && cr > 0) bySale[x.id] = { cents: cr, customerId: x.customerId };\n      });\n      Object.keys(bySale).forEach(function (id) {\n        var m = byId(s, 'ch-' + id);\n        if (!m || reversed(s, m.id)) diffs.push({ type: 'missing-charge', saleId: id, expected: pounds(bySale[id].cents) });\n        else if (m.cents !== bySale[id].cents) diffs.push({ type: 'amount-mismatch', saleId: id, expected: pounds(bySale[id].cents), ledger: pounds(m.cents) });\n        else if (bySale[id].customerId && m.customerId !== bySale[id].customerId) diffs.push({ type: 'customer-mismatch', saleId: id });\n      });\n      s.moves.forEach(function (m) {\n        if (m.type === 'charge' && !reversed(s, m.id) && !bySale[m.ref]) diffs.push({ type: 'orphan-charge', saleId: m.ref, ledger: pounds(m.cents) });\n      });\n      var live = function (t) { return s.moves.filter(function (m) { return m.type === t && !reversed(s, m.id); }).reduce(function (n, m) { return n + m.cents; }, 0); };\n      var expected = live('charge') + live('opening') - live('collection');\n      var actual = customers().reduce(function (n, c) { return n + Math.round(c.balance * 100); }, 0);\n      if (expected !== actual) diffs.push({ type: 'balance-mismatch', expected: pounds(expected), ledger: pounds(actual) });\n      return { ok: diffs.length === 0, diffs: diffs };\n    }\n\n    /* S2-05: sync helpers. allMoves = every movement (copy); importMove appends a movement from another device AS-IS, once. */\n    function allMoves() {\n      return copy(load().moves);\n    }\n    function importMove(m) {\n      if (!m || typeof m !== 'object') return { ok: false, error: 'bad-move' };\n      if (typeof m.id !== 'string' || !m.id) return { ok: false, error: 'bad-id' };\n      if (m.type !== 'opening' && m.type !== 'charge' && m.type !== 'collection' && m.type !== 'reversal') {\n        return { ok: false, error: 'bad-type' };\n      }\n      if (typeof m.customerId !== 'string' || !m.customerId) return { ok: false, error: 'bad-customer' };\n      if (typeof m.cents !== 'number' || !isFinite(m.cents) || Math.floor(m.cents) !== m.cents || m.cents <= 0) {\n        return { ok: false, error: 'bad-cents' };\n      }\n      if (m.type === 'collection' && !Array.isArray(m.allocations)) {\n        return { ok: false, error: 'bad-allocations' };\n      }\n      if (m.type === 'reversal' && (typeof m.target !== 'string' || !m.target)) {\n        return { ok: false, error: 'bad-target' };\n      }\n      var s = load();\n      if (byId(s, m.id)) return { ok: true, imported: false };\n      s.moves.push(copy(m));\n      save(s);\n      return { ok: true, imported: true };\n    }\n\n    return { setLimit: setLimit, limitOf: limitOf, openingBalance: openingBalance, charge: charge, collect: collect, reverse: reverse,\n      balance: balance, aging: aging, statement: statement, customers: customers, totalOutstanding: totalOutstanding, reconcile: reconcile,\n      allMoves: allMoves, importMove: importMove };\n  }\n\n  var api = { createCreditLedger: createCreditLedger };\n  if (typeof module !== 'undefined' && module.exports) module.exports = api;\n  else root.NovaCredit = api;\n})(typeof window !== 'undefined' ? window : this);\n","type":"application/javascript"},"/auth-local.js":{"body":"/* NOVA Rx — SEC-01 individual local accounts, sessions and trusted devices (MOCK auth: on-device only, no server, no real security boundary).\n   Replaces a shared PIN: every person has their own name + password (salted SHA-256 via WebCrypto). Sessions expire and can be revoked;\n   this device is in a trusted-device list; sensitive actions (export, account changes) need a fresh re-authentication.\n   Works as a <script> (window.NovaAuth) and in Node (module.exports). */\n(function (root) {\n  'use strict';\n\n  var ROLES = ['cashier', 'pharmacist', 'store', 'accountant', 'delivery', 'manager', 'owner'];\n  var SESSION_MS = 8 * 3600 * 1000, REAUTH_MS = 5 * 60 * 1000, MIN_PW = 6;\n\n  function fail(code) { var e = new Error(code); e.code = code; throw e; }\n  function hex(buf) { return Array.prototype.map.call(new Uint8Array(buf), function (b) { return ('0' + b.toString(16)).slice(-2); }).join(''); }\n  function rid(c) { return hex(c.getRandomValues(new Uint8Array(12))); }\n\n  function create(opts) {\n    var storage = opts.storage, c = opts.crypto, nowMs = opts.now || function () { return Date.now(); };\n    var K = { acc: 'nova.auth.accounts', ses: 'nova.auth.sessions', dev: 'nova.auth.devices', me: 'nova.auth.deviceId', cur: 'nova.auth.current' };\n    function read(k, d) { try { var v = JSON.parse(storage.getItem(k)); return v == null ? d : v; } catch (e) { return d; } }\n    function write(k, v) { storage.setItem(k, JSON.stringify(v)); }\n    function hash(salt, pw) { return c.subtle.digest('SHA-256', new TextEncoder().encode(salt + ':' + pw)).then(hex); }\n    function norm(n) { return String(n == null ? '' : n).trim(); }\n    function iso(ms) { return new Date(ms).toISOString(); }\n\n    function deviceId() {\n      var id = storage.getItem(K.me);\n      if (!id) { id = 'dev-' + rid(c); storage.setItem(K.me, id); }\n      return id;\n    }\n    function accounts() { return read(K.acc, []); }\n    function pub(a) { return { id: a.id, name: a.name, role: a.role, createdAt: a.createdAt }; }\n    function findByName(n) { var k = norm(n).toLowerCase(); return accounts().filter(function (a) { return a.name.toLowerCase() === k; })[0]; }\n    function sessions() { return read(K.ses, []); }\n    function activeSession() {\n      var id = storage.getItem(K.cur); if (!id) return null;\n      var s = sessions().filter(function (x) { return x.id === id; })[0];\n      if (!s || s.revoked || Date.parse(s.expiresAt) <= nowMs()) { storage.removeItem(K.cur); return null; }\n      return s;\n    }\n    function trust(label) {\n      var id = deviceId(), list = read(K.dev, []), d = list.filter(function (x) { return x.id === id; })[0];\n      if (d) d.lastSeen = iso(nowMs());\n      else list.push({ id: id, label: norm(label) || 'This device', addedAt: iso(nowMs()), lastSeen: iso(nowMs()) });\n      write(K.dev, list);\n    }\n\n    var api = {\n      ROLES: ROLES,\n      deviceId: deviceId,\n      accounts: function () { return accounts().map(pub); },\n      hasAccounts: function () { return accounts().length > 0; },\n      /* First account becomes the owner. Later accounts need a fresh re-auth by an owner/manager. */\n      createAccount: function (o) {\n        var name = norm(o && o.name), role = o && o.role, pw = String((o && o.password) || '');\n        if (!name || name.length > 60) fail('bad-name');\n        if (pw.length < MIN_PW) fail('weak-password');\n        var first = !accounts().length;\n        if (!first) {\n          if (!this.recentlyAuthenticated()) fail('reauth-required');\n          var me = this.current(); if (!me || (me.role !== 'owner' && me.role !== 'manager')) fail('permission');\n        } else role = 'owner';\n        if (ROLES.indexOf(role) < 0) fail('bad-role');\n        if (!first && this.current().role !== 'owner' && (role === 'owner' || role === 'manager')) fail('permission'); /* no escalation: only an owner grants owner/manager */\n        if (findByName(name)) fail('duplicate-name');\n        var salt = rid(c);\n        return hash(salt, pw).then(function (h) {\n          var list = accounts(), a = { id: 'acc-' + rid(c), name: name, role: role, salt: salt, hash: h, createdAt: iso(nowMs()) };\n          list.push(a); write(K.acc, list); return pub(a);\n        });\n      },\n      /* Mock sign-in: checks the salted hash, opens an expiring session and trusts this device. */\n      signIn: function (name, password) {\n        var a = findByName(name);\n        return hash(a ? a.salt : 'x', String(password || '')).then(function (h) {\n          if (!a || h !== a.hash) fail('bad-credentials');\n          var t = nowMs(), s = { id: 'ses-' + rid(c), accountId: a.id, deviceId: deviceId(), startedAt: iso(t), expiresAt: iso(t + SESSION_MS), lastAuthAt: iso(t), revoked: false };\n          var all = sessions().filter(function (x) { return !x.revoked && Date.parse(x.expiresAt) > t; }); all.push(s);\n          write(K.ses, all); storage.setItem(K.cur, s.id); trust(); return s;\n        });\n      },\n      /* AUDIT-02: check another account's password WITHOUT touching the current session (approvals). Never stores the password. */\n      verifyAccount: function (name, password) {\n        var a = findByName(name);\n        return hash(a ? a.salt : 'x', String(password || '')).then(function (h) {\n          if (!a || h !== a.hash) return null;\n          return { id: a.id, name: a.name, role: a.role };\n        });\n      },\n      /* SEC-01 (S1-07): after the SERVER verified name + password (staff-gate.js, POST /api/v1/auth/login 200), mirror that account\n         on this device (same name, server role, salted hash of the same password) and sign in locally, so the pharmacist can keep\n         working offline on this device later. Only staff-gate.js calls it, and only with a server-confirmed role. */\n      adoptVerified: function (o) {\n        var name = norm(o && o.name), role = o && o.role, pw = String((o && o.password) || '');\n        if (!name || name.length > 60) fail('bad-name');\n        if (ROLES.indexOf(role) < 0) fail('bad-role');\n        if (!pw) fail('bad-credentials');\n        var self = this, salt = rid(c);\n        return hash(salt, pw).then(function (h) {\n          var list = accounts(), a = findByName(name);\n          if (a) list.forEach(function (x) { if (x.id === a.id) { x.salt = salt; x.hash = h; x.role = role; } });\n          else list.push({ id: 'acc-' + rid(c), name: name, role: role, salt: salt, hash: h, createdAt: iso(nowMs()), server: true });\n          write(K.acc, list);\n          return self.signIn(name, pw);\n        });\n      },\n      signOut: function () { var id = storage.getItem(K.cur); if (id) { var all = sessions(); all.forEach(function (s) { if (s.id === id) s.revoked = true; }); write(K.ses, all); } storage.removeItem(K.cur); },\n      current: function () {\n        var s = activeSession(); if (!s) return null;\n        var a = accounts().filter(function (x) { return x.id === s.accountId; })[0];\n        return a ? { id: a.id, name: a.name, role: a.role, sessionId: s.id, expiresAt: s.expiresAt } : null;\n      },\n      /* Password check again for the current session; opens a short window for sensitive actions. */\n      reauthenticate: function (password) {\n        var s = activeSession(); if (!s) fail('no-session');\n        var a = accounts().filter(function (x) { return x.id === s.accountId; })[0];\n        return hash(a.salt, String(password || '')).then(function (h) {\n          if (h !== a.hash) fail('bad-credentials');\n          var all = sessions(); all.forEach(function (x) { if (x.id === s.id) x.lastAuthAt = iso(nowMs()); }); write(K.ses, all); return true;\n        });\n      },\n      recentlyAuthenticated: function () { var s = activeSession(); return !!s && nowMs() - Date.parse(s.lastAuthAt) <= REAUTH_MS; },\n      /* Gate for export and other sensitive changes. With no accounts yet there is nobody to authenticate: allowed (documented limit). */\n      sensitiveAllowed: function () { return !this.hasAccounts() || this.recentlyAuthenticated(); },\n      sessions: function () {\n        var t = nowMs(), cur = storage.getItem(K.cur), names = {};\n        accounts().forEach(function (a) { names[a.id] = a.name; });\n        return sessions().filter(function (s) { return !s.revoked && Date.parse(s.expiresAt) > t; })\n          .map(function (s) { return { id: s.id, account: names[s.accountId] || '?', deviceId: s.deviceId, startedAt: s.startedAt, expiresAt: s.expiresAt, current: s.id === cur }; });\n      },\n      revokeSession: function (id) {\n        var all = sessions(), hit = false; all.forEach(function (s) { if (s.id === id && !s.revoked) { s.revoked = true; hit = true; } });\n        if (!hit) fail('not-found'); write(K.ses, all); if (storage.getItem(K.cur) === id) storage.removeItem(K.cur); return true;\n      },\n      trustedDevices: function () { var me = deviceId(); return read(K.dev, []).map(function (d) { return { id: d.id, label: d.label, addedAt: d.addedAt, lastSeen: d.lastSeen, thisDevice: d.id === me }; }); },\n      /* Removing a device also revokes every session opened on it. */\n      removeDevice: function (id) {\n        var list = read(K.dev, []), next = list.filter(function (d) { return d.id !== id; });\n        if (next.length === list.length) fail('not-found');\n        write(K.dev, next);\n        var all = sessions(); all.forEach(function (s) { if (s.deviceId === id) s.revoked = true; }); write(K.ses, all);\n        var cur = activeSession(); if (!cur) storage.removeItem(K.cur);\n        return true;\n      }\n    };\n    return api;\n  }\n\n  var api = { create: create, SESSION_MS: SESSION_MS, REAUTH_MS: REAUTH_MS, MIN_PASSWORD: MIN_PW };\n  if (typeof module !== 'undefined' && module.exports) module.exports = api;\n  else {\n    root.NovaAuth = api;\n    try { root.novaAuth = create({ storage: root.localStorage, crypto: root.crypto }); } catch (e) {}\n  }\n})(typeof window !== 'undefined' ? window : globalThis);\n","type":"application/javascript"},"/auth-permissions.js":{"body":"/* NOVA Rx — SEC-02 permissions matrix (UI/local only: a client-side check on this device, NOT a security boundary; server enforcement is out of scope while the backend is frozen).\n   Roles x actions, deny by default. Denied actions are logged on this device. With no accounts yet nobody can be authenticated: allowed (same documented limit as SEC-01).\n   Works as a <script> (window.NovaPerms / window.novaPerms) and in Node (module.exports). */\n(function (root) {\n  'use strict';\n\n  var ROLES = ['owner', 'manager', 'pharmacist', 'cashier', 'store', 'accountant', 'delivery'];\n  var ACTIONS = ['sale.create', 'sale.return', 'sale.cancel', 'data.export', 'data.import', 'stock.adjust', 'prices.edit', 'reports.view', 'accounts.manage', 'purchases.manage', 'delivery.update'];\n  var MATRIX = {\n    owner: ACTIONS.slice(),\n    // managers add staff, but auth-local stops them granting owner/manager\n    manager: ['sale.create', 'sale.return', 'sale.cancel', 'data.export', 'data.import', 'stock.adjust', 'prices.edit', 'reports.view', 'accounts.manage', 'purchases.manage', 'delivery.update'],\n    pharmacist: ['sale.create', 'sale.return', 'stock.adjust', 'reports.view'],\n    cashier: ['sale.create', 'sale.return'],\n    store: ['stock.adjust', 'purchases.manage'],\n    accountant: ['data.export', 'reports.view'],\n    delivery: ['delivery.update']\n  };\n  Object.freeze(ROLES); Object.freeze(ACTIONS);\n  Object.keys(MATRIX).forEach(function (r) { Object.freeze(MATRIX[r]); }); Object.freeze(MATRIX);\n\n  var LOG_KEY = 'nova.perm.denied', LOG_MAX = 200;\n\n  function create(opts) {\n    var storage = opts.storage, who = opts.current || function () { return null; }, hasAccounts = opts.hasAccounts || function () { return false; };\n    var nowMs = opts.now || function () { return Date.now(); };\n    function readLog() { try { var v = JSON.parse(storage.getItem(LOG_KEY)); return Array.isArray(v) ? v : []; } catch (e) { return []; } }\n    function logDenied(action, me, why) {\n      var l = readLog(); l.push({ at: new Date(nowMs()).toISOString(), action: String(action), account: me ? me.name : null, role: me ? me.role : null, why: why });\n      try { storage.setItem(LOG_KEY, JSON.stringify(l.slice(-LOG_MAX))); } catch (e) {}\n    }\n    /* Role comes only from the signed-in session record, never from a caller argument, so a screen cannot ask on behalf of a stronger role. */\n    function decide(action) {\n      if (ACTIONS.indexOf(action) < 0) return { ok: false, why: 'unknown-action' };\n      if (!hasAccounts()) return { ok: true, why: 'no-accounts' };\n      var me = who(); if (!me) return { ok: false, why: 'signed-out' };\n      var allowed = MATRIX[me.role]; if (!allowed) return { ok: false, why: 'unknown-role' };\n      return allowed.indexOf(action) >= 0 ? { ok: true, why: 'role' } : { ok: false, why: 'role-denied' };\n    }\n    return {\n      /* Pure query, no log. */\n      can: function (action) { return decide(action).ok; },\n      /* Use at the moment of the action: logs a denial and returns false. */\n      require: function (action) { var d = decide(action); if (!d.ok) logDenied(action, who(), d.why); return d.ok; },\n      denied: function () { return readLog(); },\n      clearDenied: function () { storage.removeItem(LOG_KEY); },\n      matrix: function () { return ROLES.map(function (r) { return { role: r, actions: MATRIX[r].slice() }; }); }\n    };\n  }\n\n  var api = { create: create, ROLES: ROLES, ACTIONS: ACTIONS, MATRIX: MATRIX };\n  if (typeof module !== 'undefined' && module.exports) module.exports = api;\n  else {\n    root.NovaPerms = api;\n    root.novaPerms = null;\n    function boot() { try { var A = root.novaAuth; if (A) root.novaPerms = create({ storage: root.localStorage, current: function () { return A.current(); }, hasAccounts: function () { return A.hasAccounts(); } }); } catch (e) {} }\n    boot(); if (!root.novaPerms) root.addEventListener('DOMContentLoaded', boot);\n  }\n})(typeof window !== 'undefined' ? window : globalThis);\n","type":"application/javascript"},"/auth-ui.js":{"body":"/* NOVA Rx — SEC-01 UI for auth-local.js: accounts card in Settings + re-authentication dialog (mock auth, on-device). */\n(function () {\n  'use strict';\n  var A = function () { return window.novaAuth; };\n  var en = function () { return document.documentElement.lang === 'en'; };\n  var tr = function (ar, e) { return en() ? e : ar; };\n  var esc = function (s) { return String(s).replace(/[&<>\"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]; }); };\n  var ERR = {\n    'bad-credentials': ['الاسم أو كلمة المرور غير صحيحة', 'Wrong name or password'], 'weak-password': ['كلمة المرور أقل من 6 أحرف', 'Password is shorter than 6 characters'],\n    'bad-name': ['الاسم غير صالح', 'Invalid name'], 'duplicate-name': ['الاسم مستخدم', 'Name already used'], 'reauth-required': ['أكّد كلمة المرور أولًا', 'Confirm your password first'],\n    'permission': ['ليس لديك صلاحية', 'Not allowed for your role'], 'no-session': ['سجّل الدخول أولًا', 'Sign in first']\n  };\n  var ROLE_AR = { owner: 'المالك', manager: 'المدير', pharmacist: 'الصيدلي', cashier: 'الكاشير', store: 'المخزن', accountant: 'المحاسب', delivery: 'المندوب' };\n  var ACT_AR = { 'sale.create': 'إنشاء بيع', 'sale.return': 'مرتجع بيع', 'sale.cancel': 'إلغاء بيع', 'data.export': 'تصدير البيانات', 'data.import': 'استيراد البيانات', 'stock.adjust': 'تعديل المخزون', 'prices.edit': 'تعديل الأسعار', 'reports.view': 'عرض التقارير', 'accounts.manage': 'إدارة الحسابات', 'purchases.manage': 'إدارة المشتريات', 'delivery.update': 'تحديث التوصيل' };\n  var roleL = function (r) { return en() ? r : (ROLE_AR[r] || r); };\n  var actL = function (a) { return en() ? a : (ACT_AR[a] || a); };\n  var msg = function (e) { var m = ERR[e && e.code]; return m ? tr(m[0], m[1]) : tr('تعذر التنفيذ', 'Could not complete'); };\n  var field = 'style=\"min-height:40px;padding:6px 10px;background:#0e1419;color:#e7ebf0;border:1px solid #303841;border-radius:6px;font-size:14px\"';\n\n  /* Asks for the password of the signed-in person; calls ok() only after a successful re-authentication. */\n  function reauth(ok) {\n    if (!A().current()) { window.alert(tr('سجّل الدخول من الإعدادات أولًا', 'Sign in from Settings first')); return; }\n    var ov = document.createElement('div'); ov.id = 'novaReauth'; ov.setAttribute('role', 'dialog'); ov.setAttribute('aria-modal', 'true');\n    ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:10000;display:flex;align-items:center;justify-content:center;padding:16px';\n    ov.innerHTML = '<div style=\"background:#14181d;color:#e7ebf0;border:1px solid #303841;border-radius:12px;max-width:360px;width:100%;padding:16px;display:grid;gap:8px\">' +\n      '<strong>' + tr('تأكيد الهوية', 'Confirm it is you') + ' — ' + esc(A().current().name) + '</strong>' +\n      '<input type=\"password\" id=\"novaReauthPw\" autocomplete=\"current-password\" placeholder=\"' + tr('كلمة المرور', 'Password') + '\" ' + field + '>' +\n      '<div id=\"novaReauthMsg\" role=\"alert\" style=\"color:#ffb4a8;min-height:18px;font-size:13px\"></div>' +\n      '<div style=\"display:flex;gap:8px\"><button type=\"button\" id=\"novaReauthOk\" class=\"nova-return-btn\" style=\"min-height:44px;flex:1\">' + tr('تأكيد', 'Confirm') + '</button><button type=\"button\" id=\"novaReauthNo\" class=\"nova-return-btn\" style=\"min-height:44px\">' + tr('إلغاء', 'Cancel') + '</button></div></div>';\n    document.body.appendChild(ov);\n    var pw = ov.querySelector('#novaReauthPw'); pw.focus();\n    var go = function () { A().reauthenticate(pw.value).then(function () { ov.remove(); ok(); }, function (e) { ov.querySelector('#novaReauthMsg').textContent = msg(e); }); };\n    ov.querySelector('#novaReauthOk').onclick = go; pw.onkeydown = function (e) { if (e.key === 'Enter') go(); };\n    ov.querySelector('#novaReauthNo').onclick = function () { ov.remove(); };\n  }\n\n  /* Runs fn now if a recent re-authentication exists (or no accounts exist yet), otherwise asks for the password first. */\n  function guard(fn) { if (A().sensitiveAllowed()) fn(); else reauth(fn); }\n\n  function mount() {\n    var host = document.getElementById('novaAuthCard'); if (!host || !A()) return;\n    var cur = A().current(), h = '<h3>' + tr('الحسابات والجلسات', 'Accounts & sessions') + '</h3>';\n    h += '<p style=\"font-size:12px;color:#9eacb9\">' + tr('تجريبي: حسابات محلية على هذا الجهاز فقط، وليست حماية حقيقية.', 'Mock: local accounts on this device only, not a real security boundary.') + '</p><div id=\"novaAuthMsg\" role=\"status\" style=\"min-height:18px;font-size:13px;color:#ffb4a8\"></div>';\n    /* SEC-01 / S1-07: only an owner or manager sees and changes accounts, sessions, devices and the permissions matrix. */\n    var mgr = !!cur && (cur.role === 'owner' || cur.role === 'manager') && (!window.novaPerms || window.novaPerms.can('accounts.manage'));\n    if (cur) {\n      h += '<p>' + tr('الدخول باسم', 'Signed in as') + ' <b>' + esc(cur.name) + '</b> (' + esc(roleL(cur.role)) + ') — ' + tr('تنتهي الجلسة', 'expires') + ' ' + esc(new Date(cur.expiresAt).toLocaleString()) + ' <button type=\"button\" id=\"novaAuthOut\" class=\"nova-page-btn\">' + tr('خروج', 'Sign out') + '</button></p>';\n      if (!mgr) h += '<p id=\"novaAuthNoManage\" style=\"font-size:13px;color:#9eacb9\">' + tr('إدارة الحسابات للمالك أو المدير فقط.', 'Only the owner or a manager can manage accounts.') + '</p>';\n      if (mgr) h += '<h4>' + tr('الجلسات النشطة', 'Active sessions') + '</h4><ul id=\"novaAuthSessions\">' + A().sessions().map(function (s) { return '<li>' + esc(s.account) + ' · ' + esc(s.deviceId.slice(0, 10)) + (s.current ? ' (' + tr('هذه', 'this') + ')' : '') + ' <button type=\"button\" class=\"nova-page-btn\" data-revoke=\"' + esc(s.id) + '\">' + tr('إنهاء', 'Revoke') + '</button></li>'; }).join('') + '</ul>';\n      if (mgr) h += '<h4>' + tr('الأجهزة الموثوقة', 'Trusted devices') + '</h4><ul id=\"novaAuthDevices\">' + A().trustedDevices().map(function (d) { return '<li>' + esc(d.label) + ' · ' + esc(d.id.slice(0, 10)) + (d.thisDevice ? ' (' + tr('هذا الجهاز', 'this device') + ')' : '') + ' <button type=\"button\" class=\"nova-page-btn\" data-untrust=\"' + esc(d.id) + '\">' + tr('إزالة', 'Remove') + '</button></li>'; }).join('') + '</ul>';\n    } else {\n      h += '<form class=\"nova-auth-form\" id=\"novaAuthForm\" onsubmit=\"return false\"><h4>' + tr('تسجيل الدخول', 'Sign in') + '</h4><input id=\"novaAuthName\" placeholder=\"' + tr('الاسم', 'Name') + '\" maxlength=\"60\" autocomplete=\"username\" aria-describedby=\"novaAuthHint\" ' + field + '><input id=\"novaAuthPw\" type=\"password\" placeholder=\"' + tr('كلمة المرور', 'Password') + '\" autocomplete=\"current-password\" aria-describedby=\"novaAuthHint\" ' + field + '><small id=\"novaAuthHint\" class=\"nova-auth-help\">' + tr('أدخل الاسم وكلمة المرور ثم اضغط دخول.', 'Enter your name and password, then press Sign in.') + '</small><button type=\"submit\" id=\"novaAuthIn\" class=\"nova-page-btn\">' + tr('دخول', 'Sign in') + '</button></form>';\n    }\n    if (!A().hasAccounts()) h += '<p style=\"font-size:12px\">' + tr('لا توجد حسابات: أول حساب يُنشأ يصبح المالك.', 'No accounts yet: the first one created becomes the owner.') + '</p>';\n    if (!A().hasAccounts() || mgr) {\n      h += '<details><summary>' + tr('إضافة حساب', 'Add account') + '</summary><div class=\"nova-auth-form\" id=\"novaNewForm\"><input id=\"novaNewName\" placeholder=\"' + tr('الاسم', 'Name') + '\" maxlength=\"60\" ' + field + '><input id=\"novaNewPw\" type=\"password\" placeholder=\"' + tr('كلمة المرور (6+)', 'Password (6+)') + '\" ' + field + '><select id=\"novaNewRole\" aria-label=\"' + tr('الدور', 'Role') + '\" ' + field + '>' + A().ROLES.filter(function (r) { return !cur || cur.role === 'owner' || (r !== 'owner' && r !== 'manager'); }).map(function (r) { return '<option value=\"' + r + '\">' + roleL(r) + '</option>'; }).join('') + '</select><button type=\"button\" id=\"novaNewOk\" class=\"nova-page-btn\" aria-label=\"' + tr('إنشاء حساب', 'Create account') + '\">' + tr('إنشاء', 'Create') + '</button></div></details>';\n    }\n    if (mgr || !A().hasAccounts()) h += permsHtml();\n    if (!document.getElementById('novaAuthCss')) { var st = document.createElement('style'); st.id = 'novaAuthCss'; st.textContent = '.nova-auth-form{display:grid;gap:var(--sp-2,8px);width:100%;max-width:420px;box-sizing:border-box;margin:8px 0;padding:14px 16px;background:#11181e;border:1px solid #303841;border-radius:10px}.nova-auth-form h4{margin:0 0 2px}.nova-auth-form input,.nova-auth-form select{width:100%;box-sizing:border-box}.nova-auth-form input:focus-visible,.nova-auth-form select:focus-visible{outline:2px solid #4b7185;outline-offset:1px}.nova-auth-form input[aria-invalid=true]{border-color:#ff8a78!important}.nova-auth-help{color:#9eacb9;font-size:12px}'; document.head.appendChild(st); }\n    host.innerHTML = h;\n    var m = function (t) { host.querySelector('#novaAuthMsg').textContent = t; }, done = function (p) { return p.then(mount, function (e) { m(msg(e)); }); }, $ = function (s) { return host.querySelector(s); };\n    if ($('#novaAuthIn')) $('#novaAuthIn').onclick = function () { ['#novaAuthName', '#novaAuthPw'].forEach(function (q) { $(q).setAttribute('aria-invalid', $(q).value ? 'false' : 'true'); }); if (!$('#novaAuthName').value || !$('#novaAuthPw').value) { m(tr('الاسم وكلمة المرور مطلوبان', 'Name and password are required')); return; } done(A().signIn($('#novaAuthName').value, $('#novaAuthPw').value)); };\n    if ($('#novaAuthOut')) $('#novaAuthOut').onclick = function () { if (window.novaStaff && window.novaStaff.logout) window.novaStaff.logout(); else A().signOut(); mount(); };\n    host.querySelectorAll('[data-revoke]').forEach(function (b) { b.onclick = function () { if (!allow('accounts.manage')) return; guard(function () { A().revokeSession(b.dataset.revoke); mount(); }); }; });\n    host.querySelectorAll('[data-untrust]').forEach(function (b) { b.onclick = function () { if (!allow('accounts.manage')) return; guard(function () { A().removeDevice(b.dataset.untrust); mount(); }); }; });\n    if ($('#novaNewOk')) $('#novaNewOk').onclick = function () {\n      var go = function () { try { done(A().createAccount({ name: $('#novaNewName').value, password: $('#novaNewPw').value, role: $('#novaNewRole').value })); } catch (e) { m(msg(e)); } };\n      if (A().hasAccounts()) { if (!allow('accounts.manage')) return; guard(go); } else go();\n    };\n  }\n\n  /* Permissions matrix card (read-only view) + the denied-actions log. */\n  function permsHtml() {\n    var P = window.NovaPerms; if (!P) return '';\n    var h = '<details id=\"novaPermDetails\"><summary>' + tr('مصفوفة الصلاحيات (للمدير)', 'Permissions matrix (manager)') + '</summary><div style=\"overflow:auto\"><table id=\"novaPermMatrix\" style=\"border-collapse:collapse;font-size:12px\"><thead><tr><th></th>' + P.ROLES.map(function (r) { return '<th style=\"padding:2px 6px\">' + roleL(r) + '</th>'; }).join('') + '</tr></thead><tbody>';\n    P.ACTIONS.forEach(function (a) { h += '<tr><td style=\"padding:2px 6px\">' + esc(actL(a)) + '</td>' + P.ROLES.map(function (r) { return '<td style=\"text-align:center\">' + (P.MATRIX[r].indexOf(a) >= 0 ? '✓' : '–') + '</td>'; }).join('') + '</tr>'; });\n    h += '</tbody></table></div></details>';\n    var d = window.novaPerms ? window.novaPerms.denied().slice(-10).reverse() : [];\n    h += '<h4>' + tr('محاولات مرفوضة', 'Denied actions') + '</h4><ul id=\"novaPermDenied\">' + (d.length ? d.map(function (x) { return '<li>' + esc(x.at.slice(0, 19)) + ' · ' + esc(x.account || '-') + ' (' + esc(x.role ? roleL(x.role) : '-') + ') · ' + esc(actL(x.action)) + ' · ' + esc(x.why) + '</li>'; }).join('') : '<li>' + tr('لا شيء', 'None') + '</li>') + '</ul>';\n    return h;\n  }\n  function deny() { window.alert(tr('ليس لديك صلاحية لهذا الإجراء', 'Your role is not allowed to do this')); }\n  /* True if the signed-in role may do `action`; otherwise logs the denial, tells the user and returns false. */\n  function allow(action) { if (window.novaPerms && !window.novaPerms.require(action)) { deny(); return false; } return true; }\n\n  window.novaAuthUI = { allow: allow, mount: mount, reauth: reauth, guard: guard };\n})();\n","type":"application/javascript"},"/sw.js":{"body":"const NOVA_APP_ASSETS=[\"/assets/app-010-receipt-corrections.4354daa41c.js\",\"/assets/app-020-wa-home-screen-name.72f7f62119.js\",\"/assets/app-030-nova-push-card-js.a903f40dff.js\",\"/assets/app-040-base-theme.db2042f74a.css\",\"/assets/app-050-nova-sale-polish.3b6fbcc346.css\",\"/assets/app-060-ux10-mobile-sale.74bec81baf.css\",\"/assets/app-070-wa-standalone-fill.fd54237fcb.css\",\"/assets/app-080-ahmed-ux-small-batch.96453541a5.css\",\"/assets/app-090-nova-pur02-css.feedf24877.css\",\"/assets/app-100-ux-p40-sale-rail.ee214caa75.css\",\"/assets/app-110-sale-rail-held.028b77fc58.js\",\"/assets/app-120-pos-core.529f9478c6.js\",\"/assets/app-130-pages-nav.1817161aa4.js\",\"/assets/app-570-sale-approval.f801360a9e.js\",\"/assets/app-140-ui-language.681dcf62c0.js\",\"/assets/app-150-sticker-fab.42932110d7.css\",\"/assets/app-160-ai-labels-panel.d82dac5e80.js\",\"/assets/app-170-inventory-chips.7e676e1756.css\",\"/assets/app-180-sticker-studio.43b2e8493e.css\",\"/assets/app-190-sticker-studio.e8e59489d9.js\",\"/assets/app-200-nova-sticker-oneclick.69fbacadfc.css\",\"/assets/app-210-nova-sticker-oneclick-v2.459fc609be.css\",\"/assets/app-220-fix43-inbox-lib.183c7a34ba.js\",\"/assets/app-230-inbox-wa.26bd955b78.js\",\"/assets/app-240-ux209-wa-target.7cb40295c1.css\",\"/assets/app-250-sale01-backend-flag.eba3d63ec7.js\",\"/assets/app-260-sale06-onboarding.1c590f4999.js\",\"/assets/app-270-ux81-wa-badge.6a689d762e.js\",\"/assets/app-280-ux44-mobile-totals.22ae2004d6.css\",\"/assets/app-290-mobile-discount.38e3aed93a.js\",\"/assets/app-300-nova-fix50-vv.fb5a7598b8.js\",\"/assets/app-310-nav-chevrons.2164eb1f48.js\",\"/assets/app-320-ux430-wa-kpi-css.e7a4062fb3.css\",\"/assets/app-330-ux430-wa-kpi.94e61d3779.js\",\"/assets/app-340-offline-outbox.6fa02102a7.js\",\"/assets/app-350-stock-ledger.da91cd00f5.js\",\"/assets/app-360-backend-client.8ccb281466.js\",\"/assets/app-370-credit-sync.bdf7f5ee18.js\",\"/assets/app-380-receipt-sync.b230ffd476.js\",\"/assets/app-390-shift-sync.858eb60856.js\",\"/assets/app-400-po-sync.2d4023b480.js\",\"/assets/app-410-device-gateway.de1e66f148.js\",\"/assets/app-420-device-print.1373050d6f.js\",\"/assets/app-430-pos-sync.80b5460f00.js\",\"/assets/app-440-home-dashboard.d8380ec354.js\",\"/assets/app-450-nova-setup-wizard-css.1912152f61.css\",\"/assets/app-460-ux-p31-po-store.3f78c2de47.js\",\"/assets/app-470-ux-p38-settings-sections.764222a9a7.js\",\"/assets/app-480-ux-p30-receiving.c2dd2cfd32.css\",\"/assets/app-490-nova-ui-system.df5f00b027.css\",\"/assets/app-500-receiving.4d39a544ea.js\",\"/assets/app-510-ux206-mobile-cart-row.3eeb883d92.css\",\"/assets/app-520-ux422-app-skin.4b597b7814.css\",\"/assets/app-530-nova-info-tips.7e85f17416.js\",\"/assets/app-548-nova-providers.63cceacd1f.js\",\"/assets/app-550-supplier-accounts-ui.da0e87d589.js\",\"/assets/app-552-supplier-returns.29df5538d0.js\",\"/assets/app-554-item-card.b257e53edb.js\",\"/assets/app-556-credit-limit.5f97d1eb4d.js\",\"/assets/app-558-full-backup.b701ef80ed.js\",\"/assets/app-560-controlled-drugs.bf456491a6.js\",\"/assets/app-564-sensitive-log.7e48dbcb0b.js\",\"/assets/app-566-owner-dashboard.61072010e6.js\",\"/assets/app-572-sale-settings.673c2fbad0.js\",\"/assets/app-574-excel-export.c1c71e823b.js\",\"/assets/app-576-shift-open.048a78672b.js\",\"/assets/app-578-profit-slow.6ae8fe4fee.js\",\"/assets/app-580-sale-offers.308341a794.js\",\"/assets/app-582-stock-count.6f380f73e7.js\",\"/assets/app-584-item-limits.4d32363c1d.js\",\"/assets/app-586-fridge-log.0524f9bf35.js\",\"/assets/app-588-destruction-record.131ac97e4e.js\",\"/assets/app-590-shift-notes.9c1421db36.js\",\"/assets/app-592-customer-requests.4feb663c61.js\",\"/assets/app-594-ops-screens.edbde47978.js\",\"/assets/app-562-mobile-bottom-nav.471b204e6c.js\"];\n/* PERF-02: line 1 is generated by tools/split-index.mjs (content-hashed app files, precached on install from the HTTP cache the page just filled (force-cache: names are immutable), served cache-first; CACHE changes with them). */\nconst CACHE='nova-rx-shell-v7-2e9481a45e';self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(['/manifest.webmanifest','/manifest-whatsapp.webmanifest','/icon.svg']).then(()=>Promise.all(NOVA_APP_ASSETS.map(u=>c.add(new Request(u,{cache:'force-cache'})).catch(()=>null))))));self.skipWaiting()});self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))));self.clients.claim()});self.addEventListener('fetch',e=>{if(e.request.method!=='GET')return;const url=new URL(e.request.url),path=(url.pathname||'/').replace(/\\/+$/,'')||'/',wa=e.request.mode==='navigate'&&(url.searchParams.get('app')==='whatsapp'||path==='/whatsapp'||path==='/wa');if(url.origin===self.location.origin&&url.pathname.indexOf('/assets/app-')===0){e.respondWith(caches.match(e.request).then(hit=>hit||fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r})));return}e.respondWith(fetch(wa?url.href:e.request,{cache:'no-store',credentials:'same-origin'}).then(r=>{if(r.ok&&url.origin===self.location.origin&&!wa){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>wa?caches.match(url.href).then(c=>{if(c){try{const p=new URL(c.url).pathname;if(p==='/'||p==='/index.html')return Promise.reject(new Error('offline'))}catch(err){}}return c||Promise.reject(new Error('offline'))}):caches.match(e.request)))})\n/* UX406: Web Push for new customer WhatsApp messages. Payload (encrypted by the API): {kind:'wa-in',title,body,chat,chats,count,tag}.\n   Open pages get a 'nova-wa-push' message (badge/title/sound). A system notification is shown unless a NOVA tab is visible and focused. */\nself.addEventListener('push',e=>{let d={};try{d=e.data?e.data.json():{}}catch(x){d={}}if(!d||typeof d!=='object')d={};const title=String(d.title||'رسالة واتساب جديدة').slice(0,80),body=String(d.body||'').slice(0,160);e.waitUntil(self.clients.matchAll({type:'window',includeUncontrolled:true}).then(cs=>{cs.forEach(c=>{try{c.postMessage({type:'nova-wa-push',chat:d.chat||null,chats:Array.isArray(d.chats)?d.chats:[],count:Number(d.count)||1})}catch(x){}});/* iOS revokes the push subscription after a few pushes that show no notification, so every push shows one (same tag: no pile-up). */return self.registration.showNotification(title,{body,tag:String(d.tag||'nova-wa'),renotify:true,icon:'/icon.svg',badge:'/icon.svg',dir:'rtl',lang:'ar',data:{chat:d.chat||null,url:d.chat?'/whatsapp?app=whatsapp#wa':'/whatsapp?app=whatsapp#wa'}})}))});\nself.addEventListener('notificationclick',e=>{e.notification.close();const chat=(e.notification.data&&e.notification.data.chat)||null;e.waitUntil(self.clients.matchAll({type:'window',includeUncontrolled:true}).then(cs=>{const c=cs.find(x=>new URL(x.url).origin===self.location.origin);if(c){try{c.postMessage({type:'nova-wa-open',chat})}catch(x){}return c.focus?c.focus():c}return self.clients.openWindow?self.clients.openWindow('/whatsapp?app=whatsapp#wa'):null}))});\n","type":"application/javascript"},"/worker/procurement/ui-model.js":{"body":"// UI model for the supplier lookup on the sale screen (Epic #53, task 08).\n// Pure logic, dependency-free ES module; runs in the browser and Node 22.\n// Nothing in this module sends anything anywhere.\n\nimport { parseProductName } from './normalize.js';\n\nconst UNIT_WORDS = {\n  tab: 'القرص',\n  cap: 'الكبسولة',\n  sachet: 'الكيس',\n  supp: 'التحميلة',\n  amp: 'الأمبول',\n  vial: 'الفيال',\n  ml: 'المل',\n  drops: 'النقطة',\n  bottle: 'الزجاجة',\n  strip: 'الشريط',\n};\n\nexport const SUGGESTIONS_NOTE = 'بدائل اقترحها المورد (غالباً نفس المادة الفعالة، راجعها)';\n\nconst parsedCache = new Map();\nfunction parseCached(name) {\n  let hit = parsedCache.get(name);\n  if (!hit) {\n    if (parsedCache.size > 10000) parsedCache.clear();\n    hit = parseProductName(name);\n    parsedCache.set(name, hit);\n  }\n  return hit;\n}\n\nfunction round2(x) {\n  return Math.round(x * 100) / 100;\n}\n\nexport function stockUnitState(stock, lowLimit = 30) {\n  const n = Number.isFinite(Number(stock)) ? Number(stock) : 0;\n  const low = n < lowLimit;\n  return { tone: low ? 'low' : 'ok', label: low ? `الرصيد ${n} · منخفض` : `الرصيد ${n}` };\n}\n\nfunction stockLabelFor(offer) {\n  if (offer?.stockStatus === 'out_of_stock') return 'غير متوفر';\n  if (Number.isFinite(offer?.availableQuantity)) return `الرصيد ${offer.availableQuantity}`;\n  return 'متوفر';\n}\n\nfunction discountPctFor(offer, packPrice) {\n  if (Number.isFinite(offer?.discountPct)) return round2(offer.discountPct);\n  const pub = offer?.publicPrice;\n  if (Number.isFinite(pub) && pub > 0 && Number.isFinite(packPrice)) {\n    return round2((1 - packPrice / pub) * 100);\n  }\n  return null;\n}\n\nfunction unitPriceLabelFor(row) {\n  const up = row.unitPriceComparable;\n  if (!Number.isFinite(up)) return '';\n  const word = UNIT_WORDS[parseCached(row.offer?.productName ?? '').pack?.unit] ?? null;\n  const price = round2(up).toFixed(2);\n  return word ? `سعر ${word} ${price} ج.م` : `سعر الوحدة ${price} ج.م`;\n}\n\n// Readable supplier names for ids that arrive without a display name.\nconst SUPPLIER_DISPLAY = { pharmaoverseas: 'PharmaOverseas', aumet: 'Aumet' };\n\nfunction toRow(row) {\n  const offer = row.offer ?? {};\n  const supplierId = String(offer.supplierId ?? '');\n  return {\n    key: `${supplierId}::${offer.sellerId ?? ''}::${offer.productName ?? ''}`,\n    supplierId,\n    supplierProductId: String(offer.supplierProductId ?? ''),\n    sellerId: offer.sellerId == null ? null : String(offer.sellerId),\n    unitPrice: Number.isFinite(offer.unitPrice) ? offer.unitPrice : null,\n    minimumOrderQuantity: offer.minimumOrderQuantity ?? 1,\n    availableQuantity: offer.availableQuantity ?? null,\n    supplierName: offer.supplierName ?? SUPPLIER_DISPLAY[supplierId] ?? supplierId,\n    sellerName: offer.sellerName ?? offer.sellerId ?? null,\n    productName: offer.productName ?? '',\n    packPrice: Number.isFinite(row.packPrice) ? round2(row.packPrice) : null,\n    publicPrice: Number.isFinite(offer.publicPrice) ? round2(offer.publicPrice) : null,\n    discountPct: discountPctFor(offer, row.packPrice),\n    stockLabel: stockLabelFor(offer),\n    stockStatus: offer.stockStatus ?? 'unknown',\n    unitPriceLabel: unitPriceLabelFor(row),\n    best: false,\n    eligible: row.eligible === true,\n    reasons: Array.isArray(row.reasons) ? [...row.reasons] : [],\n  };\n}\n\nfunction groupRows(offers) {\n  const groups = [];\n  const byId = new Map();\n  for (const raw of offers ?? []) {\n    const row = toRow(raw);\n    let g = byId.get(row.supplierId);\n    if (!g) {\n      g = { supplierId: row.supplierId, supplierName: row.supplierName, rows: [] };\n      byId.set(row.supplierId, g);\n      groups.push(g);\n    }\n    g.rows.push(row);\n  }\n  return groups;\n}\n\n// Accepts a single compareForItem result or the provider search payload\n// ({ fetchedAt, results: [compareForItem, ...alternatives], suppliers }).\nexport function buildLookupModel(compareResult, { requestedQty = 1 } = {}) {\n  void requestedQty;\n  const results = Array.isArray(compareResult?.results) ? compareResult.results : [compareResult];\n  const primary = results[0] ?? { item: null, offers: [] };\n  const altResults = results.slice(1);\n\n  const groups = groupRows(primary.offers);\n  const altGroups = altResults.map((r) => ({\n    itemName: r?.item?.name ?? r?.item?.productName ?? '',\n    groups: groupRows(r?.offers),\n  })).filter((a) => a.groups.length > 0);\n\n  let best = null;\n  for (const g of groups) {\n    for (const row of g.rows) {\n      if (!best && row.eligible) {\n        row.best = true;\n        best = row;\n      }\n    }\n  }\n\n  return {\n    title: primary.item?.name ?? primary.item?.productName ?? '',\n    best,\n    groups,\n    altGroups,\n    suggestionsNote: altGroups.length > 0 ? SUGGESTIONS_NOTE : null,\n  };\n}\n\nconst DRAFT_KEY = 'novaSupplierDraft';\n\nfunction clampQty(qty) {\n  const n = Math.floor(Number(qty));\n  if (!Number.isFinite(n) || n < 1) return 1;\n  return Math.min(999, n);\n}\n\nexport function createDraftStore(storage) {\n  const entries = new Map();\n  try {\n    const raw = storage?.getItem?.(DRAFT_KEY);\n    if (raw) {\n      for (const e of JSON.parse(raw)) {\n        if (e && typeof e.key === 'string') entries.set(e.key, { ...e, qty: clampQty(e.qty) });\n      }\n    }\n  } catch {\n    entries.clear();\n  }\n\n  const persist = () => {\n    try {\n      storage?.setItem?.(DRAFT_KEY, JSON.stringify([...entries.values()]));\n    } catch {\n      /* storage full or unavailable: keep the in-memory draft */\n    }\n  };\n\n  return {\n    add(row, qty = 1) {\n      const existing = entries.get(row.key);\n      if (existing) {\n        existing.qty = clampQty(existing.qty + clampQty(qty));\n      } else {\n        entries.set(row.key, {\n          key: row.key,\n          row,\n          qty: clampQty(qty),\n          supplierId: row.supplierId ?? '',\n          supplierName: row.supplierName ?? row.supplierId ?? '',\n        });\n      }\n      persist();\n    },\n    setQty(key, qty) {\n      const e = entries.get(key);\n      if (!e) return;\n      e.qty = clampQty(qty);\n      persist();\n    },\n    remove(key) {\n      entries.delete(key);\n      persist();\n    },\n    list() {\n      return [...entries.values()];\n    },\n    bySupplier() {\n      const out = new Map();\n      for (const e of entries.values()) {\n        let g = out.get(e.supplierId);\n        if (!g) {\n          g = { supplierId: e.supplierId, supplierName: e.supplierName, items: [] };\n          out.set(e.supplierId, g);\n        }\n        g.items.push(e);\n      }\n      return [...out.values()];\n    },\n  };\n}\n\n","type":"application/javascript"}};
