const NOVA_PWA_ASSETS={"/manifest.webmanifest":{"body":"{\n  \"id\": \"/\",\n  \"name\": \"NOVA Rx | صيدلية السوسي\",\n  \"short_name\": \"NOVA Rx\",\n  \"description\": \"Pharmacy point of sale preview\",\n  \"start_url\": \"/\",\n  \"scope\": \"/\",\n  \"display\": \"standalone\",\n  \"orientation\": \"landscape\",\n  \"background_color\": \"#090a0d\",\n  \"theme_color\": \"#090a0d\",\n  \"icons\": [\n    {\n      \"src\": \"/icon.svg\",\n      \"sizes\": \"any\",\n      \"type\": \"image/svg+xml\",\n      \"purpose\": \"any maskable\"\n    }\n  ]\n}","type":"application/manifest+json"},"/manifest-whatsapp.webmanifest":{"body":"{\n  \"id\": \"/whatsapp\",\n  \"name\": \"NOVA WhatsApp\",\n  \"short_name\": \"NOVA WhatsApp\",\n  \"description\": \"Pharmacy WhatsApp conversations\",\n  \"start_url\": \"/whatsapp?app=whatsapp\",\n  \"scope\": \"/whatsapp\",\n  \"display\": \"standalone\",\n  \"orientation\": \"portrait\",\n  \"background_color\": \"#0A0B0E\",\n  \"theme_color\": \"#0A0B0E\",\n  \"icons\": [\n    {\n      \"src\": \"/icons/nova-whatsapp-192.png\",\n      \"sizes\": \"192x192\",\n      \"type\": \"image/png\",\n      \"purpose\": \"any\"\n    },\n    {\n      \"src\": \"/icons/nova-whatsapp-192.png\",\n      \"sizes\": \"192x192\",\n      \"type\": \"image/png\",\n      \"purpose\": \"maskable\"\n    },\n    {\n      \"src\": \"/icons/nova-whatsapp-512.png\",\n      \"sizes\": \"512x512\",\n      \"type\": \"image/png\",\n      \"purpose\": \"any\"\n    },\n    {\n      \"src\": \"/icons/nova-whatsapp-512.png\",\n      \"sizes\": \"512x512\",\n      \"type\": \"image/png\",\n      \"purpose\": \"maskable\"\n    }\n  ]\n}\n","type":"application/manifest+json"},"/icons/nova-whatsapp-180.png":{"body":"","type":"image/png","encoding":"base64"},"/icons/nova-whatsapp-192.png":{"body":"","type":"image/png","encoding":"base64"},"/icons/nova-whatsapp-512.png":{"body":"","type":"image/png","encoding":"base64"}};
/* NOVA_PWA_ASSETS_END */
/* NOVA_WA_SPA_BEGIN */
function novaWhatsAppSpaHtml(pathname, html) {
  if (!isWhatsAppPath(pathname)) return html;
  return patchWhatsAppHtml(html);
}
function isWhatsAppPath(pathname) {
  const p = String(pathname || '');
  return p === '/whatsapp' || p === '/whatsapp/' || p === '/wa' || p === '/wa/';
}
function patchWhatsAppHtml(html) {
  let out = String(html);
  for (const [a, b] of WA_HEAD_REPS) {
    if (out.includes(a)) out = out.replace(a, b);
  }
  return out;
}
